import { toast } from "sonner";
import {
  AlertTriangle,
  ArrowDownRight,
  ArrowUpRight,
  BarChart3,
  BellRing,
  BookOpen,
  CalendarDays,
  Check,
  ChevronRight,
  CircleHelp,
  ClipboardCheck,
  Cloud,
  CloudOff,
  Coffee,
  Download,
  FileText,
  LayoutDashboard,
  Loader2,
  LockKeyhole,
  LogOut,
  Menu,
  MessageCircleWarning,
  PackageSearch,
  Pencil,
  Plus,
  RefreshCw,
  Send,
  Settings2,
  ShieldCheck,
  Star,
  Store as StoreIcon,
  Target,
  Trash2,
  TrendingDown,
  TrendingUp,
  UserRound,
  UsersRound,
  X,
} from "lucide-react";
import { trpc } from "@/lib/trpc";

const IDENTITY_KEY = "oneira-identity";
const DRAFT_KEY = "oneira-report-draft";

type Identity = { role: "manager" | "admin" | "store"; name: string; storeName?: string };
type Tab = "dashboard" | "daily" | "weekly" | "monthly" | "summary" | "suggestions" | "issues";
type ReportForm = {
  id?: number; storeName: string; reportDate: string; weather: "晴" | "阴" | "雨" | "雪"; avgTicket: string; revenue: string; traffic: string;
  wasteAmount: string; wasteQty: string; tastingQty: string; tastingAmount: string; storedCount: string; storedAmount: string; praiseCount: string;
  issue: string; issueStatus: "待处理" | "处理中" | "已解决"; solver: string; solution: string; deadline: string; todayDone: string; nextPlan: string;
};

const today = () => new Date().toISOString().slice(0, 10);
const month = () => new Date().toISOString().slice(0, 7);
const n = (value: unknown) => Number(value || 0);
const money = (value: unknown) => `¥${n(value).toLocaleString("zh-CN", { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`;
const qty = (value: unknown) => n(value).toLocaleString("zh-CN", { maximumFractionDigits: 2 });
const percent = (value: number) => `${Math.max(0, Math.min(999, value)).toFixed(1)}%`;
const dateDiff = (date?: string) => date ? Math.ceil((new Date(`${date}T23:59:59`).getTime() - Date.now()) / 86400000) : 999;

function makeForm(identity: Identity, storeName?: string): ReportForm {
  return {
    storeName: identity.role === "store" ? identity.storeName || "" : storeName || "", reportDate: today(), weather: "晴", avgTicket: "", revenue: "", traffic: "", wasteAmount: "", wasteQty: "", tastingQty: "", tastingAmount: "", storedCount: "", storedAmount: "", praiseCount: "", issue: "", issueStatus: "待处理", solver: "", solution: "", deadline: "", todayDone: "", nextPlan: "",
  };
}

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "neutral" | "orange" | "red" | "green" | "blue" }) {
  const styles = { neutral: "bg-[#f2eee8] text-[#735b4a]", orange: "bg-[#fff0d4] text-[#a65f16]", red: "bg-[#ffe3e0] text-[#b74335]", green: "bg-[#def6e8] text-[#19754a]", blue: "bg-[#e3efff] text-[#3d66a4]" };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-semibold ${styles[tone]}`}>{children}</span>;
}

function SectionTitle({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: React.ReactNode }) {
  return <div className="mb-3 flex items-end justify-between gap-3"><div>{eyebrow && <div className="mb-1 text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">{eyebrow}</div>}<h2 className="text-lg font-bold tracking-tight text-[#4c2d24]">{title}</h2></div>{action}</div>;
}

function StatCard({ icon: Icon, label, value, detail, tint }: { icon: typeof Coffee; label: string; value: string; detail?: string; tint: string }) {
  return <div className="soft-card lift min-w-0 p-3.5"><div className="flex items-start justify-between"><div className={`flex h-9 w-9 items-center justify-center rounded-xl ${tint}`}><Icon size={17} /></div>{detail && <span className="text-[10px] font-semibold text-[#a88e7f]">{detail}</span>}</div><div className="mt-3 text-[11px] text-[#90786a]">{label}</div><div className="stat-number mt-0.5 truncate text-[22px] font-extrabold text-[#4b2c23]">{value}</div></div>;
}

function IdentityGate({ onEnter }: { onEnter: (identity: Identity) => void }) {
  const storesQuery = trpc.ops.publicStores.useQuery(undefined, { retry: false });
  const verifyAccess = trpc.ops.verifyAccess.useMutation();
  const [role, setRole] = useState<"manager" | "admin" | "store">("manager");
  const [name, setName] = useState("");
  const [pin, setPin] = useState("");
  const [storeName, setStoreName] = useState("");
  const [showPin, setShowPin] = useState(false);
  const submit = async () => {
    if (role === "store" && !name.trim()) { toast.error("请填写店长姓名"); return; }
    if (role === "store" && !storeName) { toast.error("请选择并绑定自己的门店"); return; }
    if (!pin) { toast.error("请输入登录口令"); return; }
    const result = await verifyAccess.mutateAsync({ role, pin, storeName: role === "store" ? storeName : undefined });
    if (!result.success) { toast.error(result.message || "口令不正确"); return; }
    onEnter(role === "store" ? { role, name: name.trim(), storeName } : { role, name: role === "admin" ? "管理员" : "运营经理" });
  };
  return <div className="flex min-h-screen items-center justify-center bg-[#f8f0e5] px-5 py-10"><div className="w-full max-w-[430px]">
    <div className="mb-8 text-center"><div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-[22px] bg-[#f29a52] text-white shadow-[0_10px_24px_rgba(219,113,57,.25)]"><span className="text-3xl">✦</span></div><div className="text-[12px] font-bold tracking-[.28em] text-[#bf744b]">ONEIRA BAKERY</div><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-[#4c2d24]">梦面包运营工作台</h1><p className="mt-2 text-sm text-[#977a69]">一份数据 · 全店同步 · 随时掌握</p></div>
    <div className="soft-card p-5 shadow-[0_20px_50px_rgba(111,66,30,.11)]"><div className="mb-4 flex items-center gap-2 text-sm font-bold text-[#58362a]"><ShieldCheck size={17} className="text-[#da7c42]" /> 请选择你的工作身份</div><div className="grid grid-cols-3 gap-1 rounded-2xl bg-[#f7f1ea] p-1"><button onClick={() => setRole("manager")} className={`rounded-xl px-2 py-2.5 text-xs font-semibold transition ${role === "manager" ? "bg-white text-[#bb5e32] shadow-sm" : "text-[#987d6e]"}`}>运营经理</button><button onClick={() => setRole("admin")} className={`rounded-xl px-2 py-2.5 text-xs font-semibold transition ${role === "admin" ? "bg-white text-[#bb5e32] shadow-sm" : "text-[#987d6e]"}`}>管理员</button><button onClick={() => setRole("store")} className={`rounded-xl px-2 py-2.5 text-xs font-semibold transition ${role === "store" ? "bg-white text-[#bb5e32] shadow-sm" : "text-[#987d6e]"}`}>我是店长</button></div>
      {role === "manager" || role === "admin" ? <div className="mt-5"><label className="mb-2 block text-xs font-semibold text-[#75594b]">{role === "admin" ? "管理员口令" : "运营经理口令"}</label><div className="relative"><LockKeyhole size={17} className="absolute left-3 top-3 text-[#b9957e]" /><input autoFocus value={pin} onChange={e => setPin(e.target.value.replace(/\D/g, "").slice(0, 12))} onKeyDown={e => e.key === "Enter" && submit()} type={showPin ? "text" : "password"} inputMode="numeric" maxLength={12} placeholder="请输入登录口令" className="h-11 w-full rounded-xl border border-[#eadbca] bg-white pl-10 pr-14 text-center tracking-[.35em] outline-none ring-[#f0a05d] focus:ring-2" /><button onClick={() => setShowPin(!showPin)} className="absolute right-3 top-2.5 rounded-lg px-1 text-xs text-[#b48d76]">{showPin ? "隐藏" : "显示"}</button></div><p className="mt-2 text-[11px] text-[#aa9182]">{role === "admin" ? "管理员可进入口令控制台和全店管理工具" : "运营经理可查看全店数据并处理运营事项"}</p></div> : <div className="mt-5 space-y-3"><div><label className="mb-2 block text-xs font-semibold text-[#75594b]">店长姓名</label><input autoFocus value={name} onChange={e => setName(e.target.value)} placeholder="例如：林晓" className="h-11 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-[#f0a05d]" /></div><div><label className="mb-2 block text-xs font-semibold text-[#75594b]">绑定自己的门店</label><select value={storeName} onChange={e => setStoreName(e.target.value)} className="h-11 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-[#f0a05d]" disabled={storesQuery.isLoading}><option value="">{storesQuery.isLoading ? "正在加载门店列表…" : "请选择门店"}</option>{storesQuery.data?.map(s => <option key={s.id} value={s.name}>{s.name} · {s.managerName}</option>)}</select><div><label className="mb-2 mt-3 block text-xs font-semibold text-[#75594b]">门店登录口令</label><div className="relative"><LockKeyhole size={17} className="absolute left-3 top-3 text-[#b9957e]" /><input value={pin} onChange={e => setPin(e.target.value.replace(/\D/g, "").slice(0, 12))} onKeyDown={e => e.key === "Enter" && submit()} type={showPin ? "text" : "password"} inputMode="numeric" maxLength={12} placeholder="请输入门店口令" className="h-11 w-full rounded-xl border border-[#eadbca] bg-white pl-10 pr-14 text-center tracking-[.35em] outline-none ring-[#f0a05d] focus:ring-2" /></div></div>{storesQuery.error && <div className="mt-2 rounded-xl bg-[#fff0ef] p-3 text-xs text-[#b74335]"><div className="flex items-center gap-1 font-semibold"><CloudOff size={14} /> 门店列表加载失败</div><div className="mt-1">请检查网络或使用官方 App 打开后重试。</div><button onClick={() => storesQuery.refetch()} className="mt-2 flex items-center gap-1 font-semibold underline"><RefreshCw size={12} /> 重新加载</button></div>}</div></div>}
      <button disabled={verifyAccess.isPending} onClick={submit} className="mt-6 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-[#e47943] text-sm font-bold text-white shadow-[0_8px_18px_rgba(215,104,55,.2)] transition hover:bg-[#d96736] disabled:opacity-60">{verifyAccess.isPending ? "验证中…" : "进入工作台"} {!verifyAccess.isPending && <ChevronRight size={17} />}</button>
    </div><div className="mt-5 flex items-center justify-center gap-2 text-[11px] text-[#ad9586]"><Cloud size={13} /> 数据加载失败会明确提示，不会静默显示空数据</div>
  </div></div>;
}

function SyncStatus({ loading, error, syncedAt }: { loading: boolean; error?: boolean; syncedAt?: Date }) {
  if (error) return <div className="flex items-center gap-1.5 rounded-full bg-[#ffe6e2] px-2.5 py-1 text-[11px] font-bold text-[#bd493b]"><CloudOff size={13} /> 离线 / 重试</div>;
  if (loading) return <div className="flex items-center gap-1.5 rounded-full bg-[#fff0d5] px-2.5 py-1 text-[11px] font-bold text-[#b66c22]"><Loader2 size={13} className="animate-spin" /> 同步中</div>;
  return <div className="flex items-center gap-1.5 rounded-full bg-[#e2f6e9] px-2.5 py-1 text-[11px] font-bold text-[#237b4d]"><span className="h-1.5 w-1.5 rounded-full bg-[#37aa66]" /> 已同步{syncedAt ? ` · ${new Date(syncedAt).toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit" })}` : ""}</div>;
}

function Field({ label, value, onChange, type = "text", placeholder, readOnly, required }: { label: string; value: string; onChange?: (value: string) => void; type?: string; placeholder?: string; readOnly?: boolean; required?: boolean }) {
  return <label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">{label}{required && <i className="ml-0.5 text-[#d66043]">*</i>}</span><input type={type} inputMode={type === "number" ? "decimal" : undefined} step={type === "number" ? "any" : undefined} value={value} onChange={e => onChange?.(e.target.value)} placeholder={placeholder} readOnly={readOnly} className={`h-10 w-full rounded-xl border border-[#eadbca] bg-[#fffdfa] px-3 text-sm text-[#55352a] outline-none focus:border-[#e59a67] focus:ring-2 focus:ring-[#f8dec2] ${readOnly ? "bg-[#f7f0e8] text-[#977a69]" : ""}`} /></label>;
}

function IssueAction({ issue, identity, onRefresh, source = "report" }: { issue: any; identity: Identity; onRefresh: () => void; source?: "report" | "store" }) {
  const [status, setStatus] = useState(issue.status || issue.issueStatus || "待处理");
  const [solver, setSolver] = useState(issue.solver || "");
  const [solution, setSolution] = useState(issue.solution || "");
  const updateReport = trpc.ops.updateIssue.useMutation({ onSuccess: () => { toast.success("问题已更新，处理闭环已同步"); onRefresh(); }, onError: e => toast.error(e.message) });
  const updateStore = trpc.ops.updateStoreIssue.useMutation({ onSuccess: () => { toast.success("问题已更新，处理闭环已同步"); onRefresh(); }, onError: e => toast.error(e.message) });
  const canHandle = identity.role === "manager" || identity.role === "admin";
  if (!canHandle) return issue.solution ? <div className="mt-2 rounded-xl bg-[#f0faf2] p-3 text-[11px] text-[#4e805d]">处理措施：{issue.solution}{issue.solver ? ` · 处理人：${issue.solver}` : ""}</div> : null;
  const save = () => source === "store" ? updateStore.mutate({ role: identity.role as "manager" | "admin", id: issue.id, status: status as any, solver, solution, deadline: issue.deadline || "" }) : updateReport.mutate({ role: identity.role as "manager" | "admin", id: issue.id, issueStatus: status as any, solver, solution, deadline: issue.deadline || "" });
  const pending = updateReport.isPending || updateStore.isPending;
  return <div className="mt-3 border-t border-[#f1e6dc] pt-3"><div className="mb-2 text-[11px] font-bold text-[#9a7563]">问题处理</div><div className="grid gap-2 sm:grid-cols-3"><select value={status} onChange={e => setStatus(e.target.value)} className="h-9 rounded-lg border border-[#eadbca] bg-white px-2 text-xs"><option>待处理</option><option>处理中</option><option>已解决</option></select><input value={solver} onChange={e => setSolver(e.target.value)} placeholder="处理人" className="h-9 rounded-lg border border-[#eadbca] bg-white px-2 text-xs" /><input value={solution} onChange={e => setSolution(e.target.value)} placeholder="处理措施 / 解决结果" className="h-9 rounded-lg border border-[#eadbca] bg-white px-2 text-xs" /></div><button disabled={pending} onClick={save} className="mt-2 rounded-lg bg-[#6b8dbd] px-3 py-2 text-[11px] font-bold text-white disabled:opacity-60">{pending ? "保存中…" : status === "已解决" ? "完成闭环" : "保存处理"}</button></div>;
}

function OpeningNodeModal({ node, identity, onClose, onRefresh }: { node: any; identity: Identity; onClose: () => void; onRefresh: () => void }) {
  const canEdit = identity.role === "manager" || identity.role === "admin";
  const [form, setForm] = useState({ storeName: node.storeName, nodeName: node.nodeName, planDate: node.planDate, owner: node.owner || "", status: node.status || (node.completed ? "已完成" : "未开始") });
  const mutation = trpc.ops.upsertNode.useMutation({ onSuccess: () => { toast.success("节点进度已同步"); onClose(); onRefresh(); }, onError: e => toast.error(e.message) });
  const deleteMutation = trpc.ops.deleteNode.useMutation({ onSuccess: () => { toast.success("筹备节点已删除"); onClose(); onRefresh(); }, onError: e => toast.error(e.message) });
  return <div className="fixed inset-0 z-[60] flex items-center justify-center p-4"><button aria-label="关闭节点详情" onClick={onClose} className="absolute inset-0 bg-[#3f281f]/40 backdrop-blur-sm" /><div className="relative max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-3xl bg-[#f8f0e5] p-5 shadow-2xl"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#7b94bd]">OPENING NODE DETAIL</div><div className="text-lg font-extrabold text-[#58372c]">节点详情与进度</div></div><button onClick={onClose} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">关闭</button></div><div className="soft-card p-4"><div className="mb-4 rounded-2xl bg-[#f0f6ff] p-3"><div className="text-sm font-extrabold text-[#4f6e9e]">{node.storeName}</div><div className="mt-1 text-xs text-[#8295b4]">点击下方状态，更新该节点完成进度</div></div>{canEdit ? <div className="grid gap-3 sm:grid-cols-2"><label className="block sm:col-span-2"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">节点名称</span><input value={form.nodeName} onChange={e => setForm({ ...form, nodeName: e.target.value })} className="h-10 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm" /></label><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">计划日期</span><input type="date" value={form.planDate} onChange={e => setForm({ ...form, planDate: e.target.value })} className="h-10 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm" /></label><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">负责人</span><input value={form.owner} onChange={e => setForm({ ...form, owner: e.target.value })} className="h-10 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm" /></label><label className="block sm:col-span-2"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">完成状态</span><select value={form.status} onChange={e => setForm({ ...form, status: e.target.value })} className="h-10 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm"><option>未开始</option><option>进行中</option><option>已完成</option></select></label><button disabled={mutation.isPending || !form.nodeName.trim() || !form.planDate || !form.owner.trim()} onClick={() => mutation.mutate({ role: identity.role as "manager" | "admin", id: node.id, ...form, completed: form.status === "已完成" } as any)} className="h-11 rounded-xl bg-[#6585b7] text-xs font-bold text-white disabled:opacity-50 sm:col-span-2">{mutation.isPending ? "保存中…" : form.status === "已完成" ? "保存并标记已完成" : "保存节点进度"}</button><button disabled={deleteMutation.isPending} onClick={() => { if (window.confirm(`确认删除节点“${node.nodeName}”吗？删除后无法恢复。`)) deleteMutation.mutate({ role: identity.role as "manager" | "admin", id: node.id }); }} className="h-10 rounded-xl border border-[#f0c9c1] bg-[#fff3f0] text-xs font-bold text-[#c65044] disabled:opacity-50 sm:col-span-2">{deleteMutation.isPending ? "删除中…" : "删除这个筹备节点"}</button></div> : <div className="space-y-3 text-sm text-[#6e5448]"><div className="flex justify-between"><span>节点名称</span><b>{node.nodeName}</b></div><div className="flex justify-between"><span>计划日期</span><b>{node.planDate}</b></div><div className="flex justify-between"><span>负责人</span><b>{node.owner || "未设置"}</b></div><div className="flex justify-between"><span>当前状态</span><Badge tone={node.status === "已完成" ? "green" : node.status === "进行中" ? "orange" : "blue"}>{node.status}</Badge></div></div>}</div></div></div>;
}


function ManagerSuggestionsCompact({ identity }: { identity: Identity }) {
  const suggestions = trpc.ops.listSuggestions.useQuery({ role: identity.role, storeName: identity.storeName, identityName: identity.name }, { retry: false });
  const [selected, setSelected] = useState<any | null>(null);
  const [reply, setReply] = useState("");
  const [status, setStatus] = useState("待查看");
  const [editTitle, setEditTitle] = useState("");
  const [editContent, setEditContent] = useState("");
  const update = trpc.ops.updateSuggestion.useMutation({ onSuccess: () => { toast.success("建议处理已同步"); setSelected(null); suggestions.refetch(); }, onError: e => toast.error(e.message) });
  const edit = trpc.ops.editSuggestion.useMutation({ onSuccess: () => { toast.success("建议内容已更新"); setSelected(null); suggestions.refetch(); }, onError: e => toast.error(e.message) });
  const remove = trpc.ops.deleteSuggestion.useMutation({ onSuccess: () => { toast.success("建议已删除"); setSelected(null); suggestions.refetch(); }, onError: e => toast.error(e.message) });
  const tone = (v: string) => v === "已采纳" ? "green" : v === "处理中" ? "blue" : v === "已回复" ? "orange" : "neutral";
  return <div className="space-y-5"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">TEAM FEEDBACK</div><h1 className="mt-1 text-2xl font-extrabold tracking-tight text-[#4c2d24]">建议处理</h1><p className="mt-1 text-sm text-[#977a69]">点击一条建议，在二级弹窗中查看内容、回复和更新状态。</p></div><div className="grid gap-3 md:grid-cols-2">{suggestions.data?.map((item: any) => <button key={item.id} onClick={() => { setSelected(item); setReply(item.reply || ""); setStatus(item.status); setEditTitle(item.title); setEditContent(item.content); }} className="soft-card flex items-center gap-3 p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#fff1df] text-[#b86a43]"><MessageCircleWarning size={17} /></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="truncate text-sm font-extrabold text-[#58372c]">{item.title}</span><Badge tone={tone(item.status) as any}>{item.status}</Badge></div><div className="mt-1 text-[11px] text-[#a18778]">{item.storeName} · {item.authorName}</div></div><ChevronRight size={16} className="text-[#c1a697]" /></button>)}</div>{suggestions.isLoading && <div className="soft-card p-8 text-center text-sm text-[#a58d7e]">正在加载建议…</div>}{!suggestions.isLoading && !suggestions.data?.length && <div className="soft-card p-10 text-center text-sm text-[#a58d7e]">还没有建议记录</div>}{selected && <div className="fixed inset-0 z-[60] flex items-center justify-center p-4"><button onClick={() => setSelected(null)} className="absolute inset-0 bg-[#3f281f]/40 backdrop-blur-sm" /><div className="relative max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-3xl bg-[#f8f0e5] p-5 shadow-2xl"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">FEEDBACK DETAIL</div><div className="text-lg font-extrabold text-[#58372c]">查看和处理建议</div></div><button onClick={() => setSelected(null)} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">关闭</button></div><div className="soft-card p-4"><div className="flex items-center gap-2"><h2 className="text-base font-extrabold text-[#58372c]">{selected.title}</h2><Badge tone={tone(selected.status) as any}>{selected.status}</Badge></div><div className="mt-1 text-[11px] text-[#a18778]">{selected.storeName} · {selected.authorName}</div><div className="mt-4 grid gap-3"><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">建议标题</span><input value={editTitle} onChange={e => setEditTitle(e.target.value)} className="h-10 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm" /></label><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">建议内容</span><textarea value={editContent} onChange={e => setEditContent(e.target.value)} className="min-h-[100px] w-full rounded-xl border border-[#eadbca] bg-white p-3 text-sm" /></label><button disabled={edit.isPending || !editTitle.trim() || !editContent.trim()} onClick={() => edit.mutate({ role: identity.role as "manager" | "admin", identityName: identity.name, identityStoreName: identity.storeName, id: selected.id, title: editTitle.trim(), content: editContent.trim() })} className="h-10 rounded-xl bg-[#e47943] text-xs font-bold text-white disabled:opacity-50">{edit.isPending ? "保存中…" : "保存建议内容"}</button></div><div className="mt-4 grid gap-3 border-t border-[#f1e6dc] pt-4"><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">处理状态</span><select value={status} onChange={e => setStatus(e.target.value)} className="h-10 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm"><option>待查看</option><option>处理中</option><option>已采纳</option><option>已回复</option></select></label><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">管理回复</span><textarea value={reply} onChange={e => setReply(e.target.value)} placeholder="填写给店长的回复" className="min-h-[100px] w-full rounded-xl border border-[#eadbca] bg-white p-3 text-sm" /></label><button disabled={update.isPending} onClick={() => update.mutate({ role: identity.role as "manager" | "admin", id: selected.id, status: status as any, reply })} className="h-11 rounded-xl bg-[#6b8dbd] text-xs font-bold text-white disabled:opacity-50">{update.isPending ? "保存中…" : "保存处理结果"}</button><button disabled={remove.isPending} onClick={() => window.confirm("确认删除这条建议吗？删除后无法恢复。") && remove.mutate({ role: identity.role as "manager" | "admin", identityName: identity.name, identityStoreName: identity.storeName, id: selected.id })} className="h-10 rounded-xl border border-[#f0c9c1] bg-[#fff3f0] text-xs font-bold text-[#c65044] disabled:opacity-50"><Trash2 size={14} className="mr-1 inline" />{remove.isPending ? "删除中…" : "删除这条建议"}</button></div></div></div></div>}</div>;
}


function IssuePicker({ issues, onSelect, onClose }: { issues: any[]; onSelect: (issue: any) => void; onClose: () => void }) {
  const pending = issues.filter((item: any) => item.issueStatus !== "已解决");
  return <div className="fixed inset-0 z-[60] flex items-center justify-center p-4"><button onClick={onClose} className="absolute inset-0 bg-[#3f281f]/40 backdrop-blur-sm" /><div className="relative max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-3xl bg-[#f8f0e5] p-5 shadow-2xl"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">ISSUE QUEUE</div><div className="text-lg font-extrabold text-[#58372c]">选择要处理的问题</div><div className="mt-1 text-xs text-[#9b8172]">共 {pending.length} 条待跟进问题，点击任意一条展开处理</div></div><button onClick={onClose} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">关闭</button></div><div className="space-y-2">{pending.map((item: any) => <button key={item.id} onClick={() => onSelect(item)} className="flex w-full items-center gap-3 rounded-2xl border border-[#f0e3d7] bg-white p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#ffe9e3] text-[#c65044]"><MessageCircleWarning size={17} /></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="truncate text-sm font-extrabold text-[#58372c]">{item.storeName}</span><Badge tone={item.issueStatus === "处理中" ? "orange" : "red"}>{item.issueStatus}</Badge></div><div className="mt-1 line-clamp-2 text-xs leading-5 text-[#71574b]">{item.issue}</div><div className="mt-1 text-[10px] text-[#a18778]">{item.reportDate} · {item.reporter}</div></div><ChevronRight size={16} className="shrink-0 text-[#c1a697]" /></button>)}{pending.length === 0 && <div className="rounded-2xl bg-[#f0faf2] p-8 text-center text-sm text-[#4e805d]">当前没有待处理问题</div>}</div></div></div>;
}

function FollowupSummary({ data, identity, setTab }: { data: any; identity: Identity; setTab: (tab: Tab) => void }) {
  const issues = data.issues || [];
  const activeIssues = issues.filter((item: any) => item.status !== "已解决");
  const suggestions = trpc.ops.listSuggestions.useQuery({ role: identity.role, storeName: identity.storeName, identityName: identity.name }, { retry: false });
  return <div><SectionTitle eyebrow="FOLLOW-UP" title="问题与建议" /><div className="grid gap-3 md:grid-cols-2"><button onClick={() => setTab("issues")} className="soft-card flex items-center gap-3 p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#ffe9e3] text-[#c65044]"><AlertTriangle size={18} /></div><div className="min-w-0 flex-1"><div className="text-sm font-extrabold text-[#58372c]">问题处理</div><div className="mt-1 text-[11px] text-[#9b8172]">{activeIssues.length} 条待跟进 · 共 {issues.length} 条记录</div></div><ChevronRight size={16} className="text-[#c1a697]" /></button><button onClick={() => setTab("suggestions")} className="soft-card flex items-center gap-3 p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#fff1df] text-[#b86a43]"><MessageCircleWarning size={18} /></div><div className="min-w-0 flex-1"><div className="text-sm font-extrabold text-[#58372c]">店长建议</div><div className="mt-1 text-[11px] text-[#9b8172]">{suggestions.data?.length || 0} 条建议 · 点击进入处理页面</div></div><ChevronRight size={16} className="text-[#c1a697]" /></button></div></div>;
}

function Dashboard({ data, identity, setTab, onRefresh }: { data: any; identity: Identity; setTab: (tab: Tab) => void; onRefresh: () => void }) {
  const [selectedNode, setSelectedNode] = useState<any | null>(null);
  const reports = data.reports || [];
  const visibleStores = data.stores || [];
  const activeReports = reports.filter((r: any) => r.reportDate === today());
  const todayRevenue = activeReports.reduce((s: number, r: any) => s + n(r.revenue), 0);
  const todayWaste = activeReports.reduce((s: number, r: any) => s + n(r.wasteAmount), 0);
  const todayStored = activeReports.reduce((s: number, r: any) => s + n(r.storedAmount), 0);
  const todayTraffic = activeReports.reduce((s: number, r: any) => s + n(r.traffic), 0);
  const operating = visibleStores.filter((s: any) => s.status === "正常运营");
  const missing = identity.role === "manager" ? Math.max(0, operating.length - activeReports.length) : 0;
  const issues = reports.filter((r: any) => r.issue);
  const overdue = issues.filter((r: any) => r.issueStatus !== "已解决" && r.deadline && r.deadline < today());
  const prep = (data.openingNodes || []).filter((node: any) => node.status !== "已完成");
  const target = visibleStores.reduce((s: number, store: any) => s + n(store.monthlyTargetWan) * 10000, 0);
  const daysInMonth = new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).getDate();
  const targetToday = target / daysInMonth;
  const completion = targetToday ? todayRevenue / targetToday * 100 : 0;
  const weekBars = [0, 1, 2, 3, 4, 5, 6].map(i => { const date = new Date(Date.now() - (6 - i) * 86400000).toISOString().slice(0, 10); return { date, value: reports.filter((r: any) => r.reportDate === date).reduce((s: number, r: any) => s + n(r.revenue), 0) }; });
  const maxBar = Math.max(1, ...weekBars.map(d => d.value));
  return <div className="space-y-5"><div className="grain relative overflow-hidden rounded-[24px] bg-[#633d30] p-5 text-white shadow-[0_16px_35px_rgba(93,52,37,.2)]"><div className="relative z-10"><div className="flex items-center justify-between"><Badge tone="orange">{identity.role === "manager" ? "总部视角" : identity.storeName}</Badge><span className="text-[11px] text-[#eed6c1]">{new Date().toLocaleDateString("zh-CN", { month: "long", day: "numeric", weekday: "short" })}</span></div><h1 className="mt-5 text-2xl font-extrabold tracking-tight">早上好，{identity.name}</h1><p className="mt-1 text-sm text-[#ecd0bd]">今天也让每一家门店，稳定地发光。</p><div className="mt-5 flex items-end justify-between"><div><div className="text-[11px] text-[#dcb9a4]">今日已交日报</div><div className="mt-1 text-3xl font-black">{activeReports.length}<span className="ml-1 text-sm font-medium text-[#dcb9a4]">/ {operating.length}</span></div></div><div className="h-16 w-28">{weekBars.map((bar, index) => <span key={bar.date} className="mx-[3px] inline-block w-[9px] rounded-t-full bg-[#e9a76c] align-bottom opacity-80" style={{ height: `${Math.max(12, bar.value / maxBar * 52)}px`, marginTop: `${64 - Math.max(12, bar.value / maxBar * 52)}px` }} />)}</div></div></div><div className="absolute -right-8 -top-14 h-48 w-48 rounded-full border-[22px] border-[#8d5941]/35" /><div className="absolute -bottom-20 right-16 h-44 w-44 rounded-full bg-[#e68e54]/15" /></div>
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><StatCard icon={TrendingUp} label="今日实收" value={money(todayRevenue)} detail="今日" tint="bg-[#fff0d4] text-[#bd6c2c]" /><StatCard icon={TrendingDown} label="今日报损" value={money(todayWaste)} detail="今日" tint="bg-[#ffe9e3] text-[#c85943]" /><StatCard icon={UsersRound} label="今日客流" value={qty(todayTraffic)} detail="人次" tint="bg-[#e5f1ff] text-[#4e76a8]" /><StatCard icon={Target} label="目标完成率" value={percent(completion)} detail="按日目标" tint="bg-[#e3f6e9] text-[#3b8a58]" /></div>
    <div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div><SectionTitle eyebrow="ACTION CENTER" title="今日待处理" action={<button onClick={() => setTab("daily")} className="text-xs font-bold text-[#c2693d]">去填报 <ChevronRight size={14} className="inline" /></button>} /><div className="soft-card divide-y divide-[#f1e5da] overflow-hidden"><button onClick={() => setTab("daily")} className="flex w-full items-center gap-3 p-4 text-left transition hover:bg-[#fffaf5]"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#fff0d4] text-[#b56b25]"><ClipboardCheck size={17} /></div><div className="min-w-0 flex-1"><div className="text-sm font-bold text-[#53342a]">今日日报待提交</div><div className="mt-0.5 text-xs text-[#9b8172]">{identity.role === "manager" ? `${missing} 家运营门店还未交日报` : "记录今天的经营数据"}</div></div><div className="text-xl font-black text-[#c8743c]">{identity.role === "manager" ? missing : "·"}</div><ChevronRight size={16} className="text-[#c4aa99]" /></button><div className="flex items-center gap-3 p-4"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#ffe5e1] text-[#c65044]"><MessageCircleWarning size={17} /></div><div className="min-w-0 flex-1"><div className="text-sm font-bold text-[#53342a]">逾期问题</div><div className="mt-0.5 text-xs text-[#9b8172]">需要运营经理跟进解决</div></div><div className="text-xl font-black text-[#c65044]">{overdue.length}</div></div><div className="flex items-center gap-3 p-4"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#e8efff] text-[#5a76b0]"><CalendarDays size={17} /></div><div className="min-w-0 flex-1"><div className="text-sm font-bold text-[#53342a]">开业节点临近</div><div className="mt-0.5 text-xs text-[#9b8172]">未来 7 天需要关注的节点</div></div><div className="text-xl font-black text-[#5a76b0]">{prep.filter((node: any) => dateDiff(node.planDate) <= 7).length}</div></div></div></div>
      <div><SectionTitle eyebrow="LIVE SIGNALS" title="经营预警" action={<Badge tone={overdue.length ? "red" : "green"}>{overdue.length ? `${overdue.length} 条需关注` : "运行正常"}</Badge>} /><div className="soft-card p-4"><div className="mb-3 flex items-center gap-2 text-sm font-bold text-[#55342a]"><BellRing size={16} className="text-[#d77f45]" /> 自动预警</div>{todayRevenue === 0 && <div className="mb-3 rounded-xl bg-[#fff6e6] p-3 text-xs text-[#a66b31]">今日还没有经营数据，提交日报后这里会自动更新。</div>}{overdue.length > 0 ? overdue.map((item: any) => <div key={item.id} className="mb-2 flex gap-2 rounded-xl bg-[#fff0ee] p-3 text-xs text-[#a8463b]"><AlertTriangle size={15} className="mt-0.5 shrink-0" /><span><b>{item.storeName}</b> 的“{item.issue}”已超过解决时限</span></div>) : <div className="rounded-xl bg-[#f0faf2] p-3 text-xs text-[#4e805d]">暂未发现逾期问题。保持日报节奏，数据会更有价值。</div>}<div className="mt-4 border-t border-[#f1e5da] pt-4"><div className="mb-2 flex justify-between text-xs text-[#8f7667]"><span>储值金额</span><b className="text-[#5e3b2d]">{money(todayStored)}</b></div><div className="h-2 overflow-hidden rounded-full bg-[#f1e6d9]"><div className="h-full rounded-full bg-[#eaaa63]" style={{ width: `${Math.min(100, todayStored / 30000 * 100)}%` }} /></div></div></div></div></div>
    <FollowupSummary data={data} identity={identity} setTab={setTab} />
    {(identity.role === "manager" || identity.role === "admin") && <div><SectionTitle eyebrow="OPENING RADAR" title="筹备 / 装修中门店" /><div className="grid gap-3 md:grid-cols-3">{visibleStores.filter((s: any) => s.status !== "正常运营").map((store: any) => { const nodes = (data.openingNodes || []).filter((node: any) => node.storeName === store.name); const done = nodes.filter((node: any) => node.completed).length; const progress = nodes.length ? done / nodes.length * 100 : 0; return <div key={store.id} className="soft-card cursor-pointer p-4 transition hover:-translate-y-0.5 hover:shadow-md" onClick={() => nodes[0] && setSelectedNode(nodes[0])}><div className="flex items-start justify-between"><div><div className="text-sm font-extrabold text-[#58372c]">{store.name}</div><div className="mt-1 text-[11px] text-[#a28777]">{store.status} · {store.openingDate || "待定"}</div></div><Badge tone={store.status === "装修中" ? "orange" : "blue"}>{store.status}</Badge></div><div className="mt-4 flex items-center justify-between text-xs text-[#927a6b]"><span>节点进度</span><b className="text-[#5b3a2d]">{done}/{nodes.length || 0}</b></div><div className="mt-2 h-2 rounded-full bg-[#f0e4d9]"><div className="h-full rounded-full bg-[#7ba7d8]" style={{ width: `${progress}%` }} /></div><div className="mt-3 space-y-1.5">{nodes.length ? nodes.map((node: any) => <button key={node.id} onClick={e => { e.stopPropagation(); setSelectedNode(node); }} className="flex w-full items-center justify-between rounded-lg bg-[#fffaf6] px-2.5 py-2 text-left text-[11px] hover:bg-[#fff0d4]"><span className="truncate font-semibold text-[#74594b]">{node.nodeName}</span><span className={`ml-2 shrink-0 font-bold ${node.status === "已完成" ? "text-[#4e805d]" : node.status === "进行中" ? "text-[#bd7533]" : "text-[#8295b4]"}`}>{node.status}</span></button>) : <div className="text-[11px] text-[#a28777]">暂无节点，点击卡片查看</div>}</div><div className="mt-2 text-[10px] text-[#a28777]">点击节点可查看详情、编辑和更新完成状态</div></div>})}</div></div>}{selectedNode && <OpeningNodeModal node={selectedNode} identity={identity} onClose={() => setSelectedNode(null)} onRefresh={onRefresh} />}
  </div>;
}


function DailyOverview({ data, identity }: { data: any; identity: Identity }) {
  const [expanded, setExpanded] = useState<number | null>(null);
  const [selectedDate, setSelectedDate] = useState(today());
  const reports = data.reports || [];
  const stores = (data.stores || []).filter((s: any) => identity.role === "manager" || identity.role === "admin" || s.name === identity.storeName);
  const todayReports = reports.filter((r: any) => r.reportDate === selectedDate);
  const submitted = stores.filter((s: any) => todayReports.some((r: any) => r.storeName === s.name));
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">DAILY OVERVIEW</div><h1 className="mt-1 text-2xl font-extrabold tracking-tight text-[#4c2d24]">当日各店汇报</h1><p className="mt-1 text-sm text-[#977a69]">按门店查看今天的日报提交情况与经营数据，经理和管理员无需重复填报。</p></div><div className="flex items-center gap-2"><input type="date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)} disabled={identity.role === "store"} className="h-10 rounded-xl border border-[#eadbca] bg-white px-3 text-xs text-[#654439]" /><Badge tone="green">已提交 {submitted.length} / {stores.length} 店</Badge></div></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><StatCard icon={ClipboardCheck} label="已提交门店" value={`${submitted.length}/${stores.length}`} detail={selectedDate} tint="bg-[#e3f6e9] text-[#3b8a58]" /><StatCard icon={TrendingUp} label="所选日实收" value={money(todayReports.reduce((sum: number, r: any) => sum + n(r.revenue), 0))} detail="所选门店" tint="bg-[#fff0d4] text-[#bd6c2c]" /><StatCard icon={UsersRound} label="所选日客流" value={qty(todayReports.reduce((sum: number, r: any) => sum + n(r.traffic), 0))} detail="人次" tint="bg-[#e5f1ff] text-[#4e76a8]" /><StatCard icon={MessageCircleWarning} label="待处理问题" value={qty(todayReports.filter((r: any) => r.issue && r.issueStatus !== "已解决").length)} detail="需要跟进" tint="bg-[#ffe9e3] text-[#c85943]" /></div><div className="grid gap-3 md:grid-cols-2">{stores.map((store: any) => { const report = todayReports.find((r: any) => r.storeName === store.name); const isExpanded = expanded === store.id; return <div key={store.id} className="soft-card overflow-hidden"><button onClick={() => setExpanded(isExpanded ? null : store.id)} className="flex w-full items-center gap-3 p-4 text-left hover:bg-[#fffaf6]"><div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${report ? "bg-[#e3f6e9] text-[#3b8a58]" : "bg-[#fff0d4] text-[#b56b25]"}`}><StoreIcon size={17} /></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="truncate text-sm font-extrabold text-[#58372c]">{store.name}</span><Badge tone={report ? "green" : "orange"}>{report ? (report.issue ? report.issueStatus : "已提交") : "待提交"}</Badge></div><div className="mt-1 text-[11px] text-[#a18778]">店长：{store.managerName || "未设置"} · {report ? `填报人：${report.reporter}` : "今天尚未提交日报"}</div></div><ChevronRight size={16} className={`shrink-0 text-[#c1a697] transition ${isExpanded ? "rotate-90" : ""}`} /></button>{isExpanded && <div className="border-t border-[#f1e6dc] bg-[#fffaf6] p-4">{report ? <div className="grid grid-cols-2 gap-3 text-xs text-[#74594b] sm:grid-cols-4"><div><div className="text-[10px] text-[#a18778]">实收</div><b>{money(report.revenue)}</b></div><div><div className="text-[10px] text-[#a18778]">报损</div><b>{money(report.wasteAmount)}</b></div><div><div className="text-[10px] text-[#a18778]">客流</div><b>{qty(report.traffic)}</b></div><div><div className="text-[10px] text-[#a18778]">好评</div><b>{qty(report.praiseCount)}</b></div>{report.issue && <div className="col-span-2 rounded-xl bg-[#fff0ee] p-3 text-[#a8463b] sm:col-span-4"><b>问题：</b>{report.issue}{report.solution && <div className="mt-1"><b>处理措施：</b>{report.solution}</div>}</div>}</div> : <div className="rounded-xl bg-[#fff6e6] p-3 text-xs text-[#a66b31]">该门店今日尚未提交日报，可联系店长补交。</div>}</div>}</div>})}</div></div>;
}


function DailyReviewPanel({ data, identity, onRefresh }: { data: any; identity: Identity; onRefresh: () => void }) {
  const [editing, setEditing] = useState<any | null>(null);
  const [date, setDate] = useState(today());
  const [content, setContent] = useState("");
  const reviews = (data.dailyReviews || []).filter((r: any) => r.reviewerName === identity.name);
  const save = trpc.ops.upsertDailyReview.useMutation({ onSuccess: () => { toast.success(editing ? "日复盘已更新" : "日复盘已保存"); setEditing(null); setDate(today()); setContent(""); onRefresh(); }, onError: e => toast.error(e.message) });
  const remove = trpc.ops.deleteDailyReview.useMutation({ onSuccess: () => { toast.success("日复盘已删除"); onRefresh(); }, onError: e => toast.error(e.message) });
  const beginEdit = (item: any) => { setEditing(item); setDate(item.reviewDate); setContent(item.content); };
  return <div className="soft-card p-4 md:p-5"><SectionTitle eyebrow="PRIVATE DAILY REVIEW" title="我的日复盘" action={<Badge tone="blue">仅本人可见</Badge>} /><p className="mb-3 text-xs text-[#9b8172]">记录当天经营复盘、亮点、问题原因和明日动作，只会显示在自己的工作台。</p><div className="grid gap-3 md:grid-cols-[180px_1fr]"><Field label="复盘日期" value={date} onChange={setDate} type="date" /><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">复盘记录</span><textarea value={content} onChange={e => setContent(e.target.value)} placeholder="今天做得好的地方、问题原因、明日改进动作" className="min-h-[100px] w-full rounded-xl border border-[#eadbca] bg-white p-3 text-sm" /></label></div><div className="mt-3 flex gap-2"><button disabled={save.isPending || !content.trim()} onClick={() => save.mutate({ role: "store", identityName: identity.name, identityStoreName: identity.storeName || "", storeName: identity.storeName || "", id: editing?.id, reviewDate: date, content: content.trim() })} className="rounded-xl bg-[#6585b7] px-4 py-2 text-xs font-bold text-white disabled:opacity-50">{save.isPending ? "保存中…" : editing ? "保存复盘修改" : "保存日复盘"}</button>{editing && <button onClick={() => { setEditing(null); setDate(today()); setContent(""); }} className="rounded-xl bg-[#f1e4d8] px-4 py-2 text-xs font-bold text-[#987d6e]">取消编辑</button>}</div><div className="mt-4 space-y-2">{reviews.map((item: any) => <div key={item.id} className="rounded-xl border border-[#e5edf8] bg-[#f8fbff] p-3"><div className="flex items-start justify-between gap-2"><div><b className="text-xs text-[#4f6e9e]">{item.reviewDate}</b><p className="mt-1 whitespace-pre-wrap text-xs leading-5 text-[#71574b]">{item.content}</p></div><div className="flex gap-1"><button onClick={() => beginEdit(item)} className="rounded-lg p-2 text-[#6b8dbd]"><Pencil size={14} /></button><button onClick={() => window.confirm("确认删除这条日复盘吗？") && remove.mutate({ role: "store", identityName: identity.name, identityStoreName: identity.storeName || "", storeName: identity.storeName || "", id: item.id })} className="rounded-lg p-2 text-[#c8786a]"><Trash2 size={14} /></button></div></div></div>)}</div></div>;
}

function DailyReports({ data, identity, onRefresh }: { data: any; identity: Identity; onRefresh: () => void }) {
  const stores = data.stores || [];
  const [form, setForm] = useState<ReportForm>(() => makeForm(identity));
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const visibleReports = (data.reports || []).filter((r: any) => !search || r.storeName.includes(search) || r.reportDate.includes(search)).slice(0, 15);
  const save = trpc.ops.upsertReport.useMutation({ onSuccess: (result) => { toast.success(result.mode === "created" ? "日报已提交，团队可同步查看" : "日报已更新"); setForm(makeForm(identity, identity.role === "store" ? identity.storeName : form.storeName)); localStorage.removeItem(DRAFT_KEY); setSaving(false); onRefresh(); }, onError: (error) => { toast.error(error.message); setSaving(false); } });
  const remove = trpc.ops.deleteReport.useMutation({ onSuccess: () => { toast.success("日报已删除"); onRefresh(); }, onError: e => toast.error(e.message) });
  useEffect(() => { const cached = localStorage.getItem(`${DRAFT_KEY}:${identity.role}:${identity.name}`); if (cached) { try { setForm(JSON.parse(cached)); } catch { /* ignore malformed local cache */ } } }, [identity.name, identity.role]);
  useEffect(() => { const timer = setTimeout(() => localStorage.setItem(`${DRAFT_KEY}:${identity.role}:${identity.name}`, JSON.stringify(form)), 250); return () => clearTimeout(timer); }, [form, identity.name, identity.role]);
  const set = (key: keyof ReportForm, value: string) => setForm(prev => ({ ...prev, [key]: value }));
  const submit = () => {
    if (!form.storeName || !form.reportDate) { toast.error("门店与报告日期为必填项"); return; }
    setSaving(true);
    const numeric = ["avgTicket", "revenue", "traffic", "wasteAmount", "wasteQty", "tastingQty", "tastingAmount", "storedCount", "storedAmount", "praiseCount"];
    const payload: any = { role: identity.role, identityName: identity.name, identityStoreName: identity.storeName, ...form, ...Object.fromEntries(numeric.map(key => [key, n(form[key as keyof ReportForm])])) };
    save.mutate(payload);
  };
  const edit = (report: any) => setForm({ ...makeForm(identity, report.storeName), id: report.id, ...Object.fromEntries(Object.entries(report).map(([k, v]) => [k, v === null ? "" : String(v)])), issueStatus: report.issueStatus || "待处理", weather: report.weather || "晴" } as ReportForm);
  return <div className="space-y-5"><div className="flex items-end justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">DAILY REPORT</div><h1 className="mt-1 text-2xl font-extrabold tracking-tight text-[#4c2d24]">日汇报</h1><p className="mt-1 text-sm text-[#977a69]">每天一份真实记录，沉淀门店经营节奏。</p></div><Badge tone="green"><Cloud size={12} className="mr-1" />多人同步</Badge></div>
    <div className="soft-card p-4 md:p-5"><div className="mb-4 flex items-center justify-between"><h2 className="font-bold text-[#55352b]">{form.id ? "编辑日报" : "填写今日日报"}</h2>{form.id && <button onClick={() => setForm(makeForm(identity, identity.role === "store" ? identity.storeName : ""))} className="text-xs font-semibold text-[#b86a43]">取消编辑</button>}</div><div className="grid grid-cols-2 gap-3 md:grid-cols-4"><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">门店<i className="ml-0.5 text-[#d66043]">*</i></span><select value={form.storeName} onChange={e => set("storeName", e.target.value)} disabled={identity.role === "store"} className="h-10 w-full rounded-xl border border-[#eadbca] bg-[#fffdfa] px-3 text-sm outline-none focus:ring-2 focus:ring-[#f8dec2]"><option value="">请选择门店</option>{stores.map((s: any) => <option key={s.id} value={s.name}>{s.name}</option>)}</select></label><Field label="报告日期" value={form.reportDate} onChange={v => set("reportDate", v)} type="date" required /><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">天气</span><select value={form.weather} onChange={e => set("weather", e.target.value)} className="h-10 w-full rounded-xl border border-[#eadbca] bg-[#fffdfa] px-3 text-sm outline-none focus:ring-2 focus:ring-[#f8dec2]"><option>晴</option><option>阴</option><option>雨</option><option>雪</option></select></label><Field label="客单价（元）" value={form.avgTicket} onChange={v => set("avgTicket", v)} type="number" placeholder="0.00" /></div>
      <div className="my-5 flex items-center gap-3 text-[11px] font-bold text-[#bf7c55]"><span className="h-px flex-1 bg-[#f0e3d7]" /> 销售与损耗 <span className="h-px flex-1 bg-[#f0e3d7]" /></div><div className="grid grid-cols-2 gap-3 md:grid-cols-4"><Field label="当日实收（元）" value={form.revenue} onChange={v => set("revenue", v)} type="number" placeholder="0.00" /><Field label="客流（人次）" value={form.traffic} onChange={v => set("traffic", v)} type="number" placeholder="0.00" /><Field label="报损金额（元）" value={form.wasteAmount} onChange={v => set("wasteAmount", v)} type="number" placeholder="0.00" /><Field label="报损数量（个）" value={form.wasteQty} onChange={v => set("wasteQty", v)} type="number" placeholder="0.00" /><Field label="试吃数量（个）" value={form.tastingQty} onChange={v => set("tastingQty", v)} type="number" placeholder="0.00" /><Field label="试吃金额（元）" value={form.tastingAmount} onChange={v => set("tastingAmount", v)} type="number" placeholder="0.00" /><Field label="储值个数（笔）" value={form.storedCount} onChange={v => set("storedCount", v)} type="number" placeholder="0.00" /><Field label="储值金额（元）" value={form.storedAmount} onChange={v => set("storedAmount", v)} type="number" placeholder="0.00" /><Field label="好评数量（条）" value={form.praiseCount} onChange={v => set("praiseCount", v)} type="number" placeholder="0.00" /></div>
      <div className="my-5 flex items-center gap-3 text-[11px] font-bold text-[#bf7c55]"><span className="h-px flex-1 bg-[#f0e3d7]" /> 工作小结 <span className="h-px flex-1 bg-[#f0e3d7]" /></div><div className="grid gap-3 md:grid-cols-2"><Field label="今日完成" value={form.todayDone} onChange={v => set("todayDone", v)} placeholder="重点事项 / 发现" /><Field label="下一步计划" value={form.nextPlan} onChange={v => set("nextPlan", v)} placeholder="明日重点" /></div>
<div className="mt-4 flex items-center justify-between gap-3"><span className="text-[11px] text-[#a68c7c]">草稿自动保存 · 所有数值支持小数</span><button disabled={saving} onClick={submit} className="flex h-11 items-center gap-2 rounded-xl bg-[#e47943] px-5 text-sm font-bold text-white shadow-[0_7px_17px_rgba(215,104,55,.2)] disabled:opacity-60">{saving ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}{saving ? "保存中…" : "提交日报"}</button></div></div>
    {identity.role === "store" && <DailyReviewPanel data={data} identity={identity} onRefresh={onRefresh} />}<div><SectionTitle title="最近汇报" action={<div className="relative"><FileText size={14} className="absolute left-3 top-2.5 text-[#b49481]" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="搜索门店或日期" className="h-9 w-40 rounded-xl border border-[#eadbca] bg-white pl-8 pr-2 text-xs outline-none focus:ring-2 focus:ring-[#f8dec2]" /></div>} /><div className="space-y-2">{visibleReports.map((report: any) => { const canEdit = identity.role === "manager" || report.reporter === identity.name; return <div key={report.id} className="soft-card flex items-center gap-3 p-3.5"><div className="flex h-10 w-10 shrink-0 flex-col items-center justify-center rounded-xl bg-[#fff0d4] text-[#aa642b]"><span className="text-[10px] font-bold">{report.reportDate.slice(5, 7)}月</span><span className="text-sm font-extrabold">{report.reportDate.slice(8)}</span></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="truncate text-sm font-bold text-[#58372c]">{report.storeName}</span>{report.issue ? <Badge tone={report.issueStatus === "已解决" ? "green" : report.issueStatus === "处理中" ? "orange" : "red"}>{report.issueStatus}</Badge> : <Badge tone="green">已提交</Badge>}</div><div className="mt-1 text-[11px] text-[#9b8172]">实收 {money(report.revenue)} · 客流 {qty(report.traffic)} · 填报人 {report.reporter}</div></div>{canEdit ? <div className="flex shrink-0 gap-1"><button onClick={() => edit(report)} className="rounded-lg p-2 text-[#a67b63] hover:bg-[#fff3e8]"><Pencil size={15} /></button><button onClick={() => window.confirm("确认删除这条日报吗？删除后无法恢复。") && remove.mutate({ role: identity.role, identityName: identity.name, identityStoreName: identity.storeName, id: report.id })} className="rounded-lg p-2 text-[#c8786a] hover:bg-[#fff0ee]"><Trash2 size={15} /></button></div> : <span className="text-[10px] text-[#b8a194]">仅可查看</span>}</div> })}{visibleReports.length === 0 && <div className="soft-card p-8 text-center text-sm text-[#a58d7e]">暂无日报记录</div>}</div></div>
  </div>;
}

function Weekly({ data, identity }: { data: any; identity: Identity }) {
  const [store, setStore] = useState(identity.role === "store" ? identity.storeName || "" : "全部门店");
  const [weekStart, setWeekStart] = useState(() => { const d = new Date(); d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return d.toISOString().slice(0, 10); });
  const weekEnd = new Date(`${weekStart}T00:00:00`); weekEnd.setDate(weekEnd.getDate() + 6);
  const weekEndText = weekEnd.toISOString().slice(0, 10);
  const reports = (data.reports || []).filter((r: any) => !store || store === "全部门店" || r.storeName === store).filter((r: any) => r.reportDate >= weekStart && r.reportDate <= weekEndText);
  const kpis = [{ label: "本周实收", value: reports.reduce((s: number, r: any) => s + n(r.revenue), 0), icon: TrendingUp }, { label: "本周报损", value: reports.reduce((s: number, r: any) => s + n(r.wasteAmount), 0), icon: TrendingDown }, { label: "本周储值", value: reports.reduce((s: number, r: any) => s + n(r.storedAmount), 0), icon: Target }, { label: "本周客流", value: reports.reduce((s: number, r: any) => s + n(r.traffic), 0), icon: UsersRound }, { label: "本周好评", value: reports.reduce((s: number, r: any) => s + n(r.praiseCount), 0), icon: Check }];
  const bars = Array.from({ length: 7 }, (_, i) => { const d = new Date(`${weekStart}T00:00:00`); d.setDate(d.getDate() + i); const date = d.toISOString().slice(0, 10); return { date, value: reports.filter((r: any) => r.reportDate === date).reduce((s: number, r: any) => s + n(r.revenue), 0) }; });
  const max = Math.max(1, ...bars.map(b => b.value));
  const [selectedBar, setSelectedBar] = useState<any | null>(null);
  return <div className="space-y-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">WEEKLY PULSE</div><h1 className="mt-1 text-2xl font-extrabold tracking-tight text-[#4c2d24]">周汇报</h1><p className="mt-1 text-sm text-[#977a69]">看趋势，也看每一天的变化。</p></div><input type="date" value={weekStart} onChange={e => setWeekStart(e.target.value)} disabled={identity.role === "store"} className="h-10 rounded-xl border border-[#eadbca] bg-white px-3 text-xs text-[#654439]" /><select value={store} onChange={e => setStore(e.target.value)} disabled={identity.role === "store"} className="h-10 rounded-xl border border-[#eadbca] bg-white px-3 text-sm text-[#654439] outline-none"><option>全部门店</option>{(data.stores || []).map((s: any) => <option key={s.id}>{s.name}</option>)}</select></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-5">{kpis.map(k => <StatCard key={k.label} icon={k.icon as any} label={k.label} value={k.label.includes("客流") || k.label.includes("好评") ? qty(k.value) : money(k.value)} detail="近 7 日" tint="bg-[#fff0d4] text-[#bd6c2c]" />)}</div><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="soft-card p-5"><div className="flex items-center justify-between"><div><div className="text-sm font-extrabold text-[#58372c]">实收趋势</div><div className="mt-1 text-xs text-[#a08677]">所选周每日门店合计</div></div><Badge tone="green">数据已同步</Badge></div><div className="mt-7 flex h-44 items-end justify-between gap-2 border-b border-[#eaded2] px-1">{bars.map(bar => <div key={bar.date} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><button onClick={() => setSelectedBar(bar)} className="relative w-full max-w-[34px] rounded-t-xl bg-gradient-to-t from-[#df7d46] to-[#f5be7b] transition-all hover:brightness-110" style={{ height: `${Math.max(8, bar.value / max * 125)}px` }} title={`${bar.date} 实收 ${money(bar.value)}`} aria-label={`${bar.date} 实收 ${money(bar.value)}`} /><span className="mb-1 text-[9px] font-bold text-[#9a5a38]">{money(bar.value)}</span><span className="text-[10px] text-[#a38a7c]">{bar.date.slice(5)}</span></div>)}</div></div><div className="soft-card p-5"><SectionTitle title="本周问题复盘" action={<Badge tone="orange">{reports.filter((r: any) => r.issue).length} 条</Badge>} />{reports.filter((r: any) => r.issue).slice(0, 5).map((r: any) => <div key={r.id} className="border-b border-[#f1e6dc] py-3 last:border-0"><div className="flex items-center justify-between gap-2"><span className="text-xs font-bold text-[#614236]">{r.storeName}</span><Badge tone={r.issueStatus === "已解决" ? "green" : "red"}>{r.issueStatus}</Badge></div><div className="mt-1 text-xs text-[#8f7668]">{r.issue}</div>{r.solution && <div className="mt-1 text-[11px] text-[#b08b74]">措施：{r.solution}</div>}</div>)}{reports.filter((r: any) => r.issue).length === 0 && <div className="py-8 text-center text-sm text-[#a58d7e]">本周暂无问题记录</div>}</div></div><div className="soft-card p-5"><div className="flex items-center gap-2 text-sm font-extrabold text-[#58372c]"><BookOpen size={16} className="text-[#ca7548]" /> 周经营小结</div><div className="mt-4 grid gap-3 md:grid-cols-2"><textarea placeholder="本周经营总结（可选）" className="min-h-[100px] rounded-xl border border-[#eadbca] bg-[#fffdfa] p-3 text-sm outline-none focus:ring-2 focus:ring-[#f8dec2]" /><textarea placeholder="下周计划（可选）" className="min-h-[100px] rounded-xl border border-[#eadbca] bg-[#fffdfa] p-3 text-sm outline-none focus:ring-2 focus:ring-[#f8dec2]" /></div><div className="mt-3 flex justify-end"><button onClick={() => toast.info("周经营总结保存入口已就绪，可继续填写") } className="rounded-xl bg-[#f3e4d7] px-4 py-2 text-xs font-bold text-[#9d5a39]">保存小结</button></div></div></div>;
}


function ProductManager({ products, stores, identity, month: currentMonth, onRefresh }: { products: any[]; stores: any[]; identity: Identity; month: string; onRefresh: () => void }) {
  const canManage = identity.role === "manager" || identity.role === "admin" || identity.role === "store";
  const [editing, setEditing] = useState<any | null>(null);
  const [form, setForm] = useState({ storeName: stores[0]?.name || "", productName: "", sales: "", category: "畅销" });
  const mutation = trpc.ops.upsertProduct.useMutation({ onSuccess: () => { toast.success(editing ? "产品排行已更新" : "产品排行已添加"); setEditing(null); onRefresh(); }, onError: e => toast.error(e.message) });
  const remove = trpc.ops.deleteProduct.useMutation({ onSuccess: () => { toast.success("产品排行已删除"); onRefresh(); }, onError: e => toast.error(e.message) });
  const beginAdd = () => { setEditing(null); setForm({ storeName: stores[0]?.name || "", productName: "", sales: "", category: "畅销" }); };
  const beginEdit = (item: any) => { setEditing(item); setForm({ storeName: item.storeName, productName: item.productName, sales: String(item.sales), category: item.category }); };
  return <div className="soft-card p-5"><SectionTitle title="本月销售排行" action={canManage && <button onClick={beginAdd} className="flex items-center gap-1 text-xs font-bold text-[#c2693d]"><Plus size={14} /> 新增产品</button>} />{canManage && <div className="mb-4 rounded-2xl bg-[#fffaf6] p-3"><div className="grid gap-2 sm:grid-cols-2"><label className="block"><span className="mb-1 block text-[11px] font-semibold text-[#75594b]">门店</span><select value={form.storeName} onChange={e => setForm({ ...form, storeName: e.target.value })} className="h-9 w-full rounded-lg border border-[#eadbca] bg-white px-2 text-xs">{stores.map(s => <option key={s.id}>{s.name}</option>)}</select></label><Field label="产品名称" value={form.productName} onChange={v => setForm({ ...form, productName: v })} placeholder="例如：海盐可颂" required /><Field label="销量（件）" value={form.sales} onChange={v => setForm({ ...form, sales: v })} type="number" placeholder="0" /><label className="block"><span className="mb-1 block text-[11px] font-semibold text-[#75594b]">分类</span><select value={form.category} onChange={e => setForm({ ...form, category: e.target.value })} className="h-9 w-full rounded-lg border border-[#eadbca] bg-white px-2 text-xs"><option>畅销</option><option>滞销</option></select></label></div><div className="mt-3 flex gap-2"><button onClick={() => mutation.mutate({ role: identity.role as "manager" | "admin" | "store", identityStoreName: identity.storeName, id: editing?.id, storeName: form.storeName, month: currentMonth, productName: form.productName.trim(), sales: n(form.sales), category: form.category as "畅销" | "滞销" })} disabled={mutation.isPending || !form.productName.trim() || !form.storeName} className="rounded-xl bg-[#e47943] px-4 py-2 text-xs font-bold text-white disabled:opacity-50">{mutation.isPending ? "保存中…" : editing ? "保存修改" : "添加排行"}</button>{editing && <button onClick={beginAdd} className="rounded-xl bg-[#f1e4d8] px-4 py-2 text-xs font-bold text-[#987d6e]">取消编辑</button>}</div></div>}{products.length ? products.slice().sort((a: any, b: any) => n(b.sales) - n(a.sales)).slice(0, 12).map((product: any, index: number) => <div key={product.id} className="flex items-center gap-3 border-b border-[#f1e6dc] py-3 last:border-0"><div className={`flex h-7 w-7 items-center justify-center rounded-lg text-xs font-black ${index < 3 ? "bg-[#fff0d4] text-[#b86a28]" : "bg-[#f4eee7] text-[#998274]"}`}>{index + 1}</div><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold text-[#604236]">{product.productName}</div><div className="mt-0.5 text-[10px] text-[#a38a7b]">{product.storeName}</div></div><div className="text-right"><Badge tone={product.category === "畅销" ? "green" : "red"}>{product.category}</Badge><div className="mt-1 text-xs font-bold text-[#755447]">{qty(product.sales)} 件</div></div>{canManage && <div className="flex gap-1"><button onClick={() => beginEdit(product)} className="rounded-lg p-2 text-[#a67b63] hover:bg-[#fff3e8]" title="编辑产品"><Pencil size={14} /></button><button onClick={() => window.confirm("确认删除这个产品排行吗？") && remove.mutate({ role: identity.role as "manager" | "admin" | "store", identityStoreName: identity.storeName, id: product.id })} className="rounded-lg p-2 text-[#c8786a] hover:bg-[#fff0ee]" title="删除产品"><Trash2 size={14} /></button></div>}</div>) : <div className="py-10 text-center text-sm text-[#a58d7e]">本月暂无产品排行数据</div>}</div>;
}


function ProductSuggestionManager({ suggestions, stores, identity, month: currentMonth, onRefresh }: { suggestions: any[]; stores: any[]; identity: Identity; month: string; onRefresh: () => void }) {
  const canManage = identity.role === "manager" || identity.role === "admin" || identity.role === "store";
  const [editing, setEditing] = useState<any | null>(null);
  const [form, setForm] = useState({ storeName: identity.storeName || stores[0]?.name || "", productName: "", type: "建议下市", reason: "" });
  const mutation = trpc.ops.upsertProductSuggestion.useMutation({ onSuccess: () => { toast.success(editing ? "产品建议已更新" : "产品建议已提交"); setEditing(null); setForm({ storeName: identity.storeName || stores[0]?.name || "", productName: "", type: "建议下市", reason: "" }); onRefresh(); }, onError: e => toast.error(e.message) });
  const remove = trpc.ops.deleteProductSuggestion.useMutation({ onSuccess: () => { toast.success("产品建议已删除"); onRefresh(); }, onError: e => toast.error(e.message) });
  const beginEdit = (item: any) => { setEditing(item); setForm({ storeName: item.storeName, productName: item.productName, type: item.type, reason: item.reason }); };
  return <div className="soft-card p-5"><SectionTitle title="产品上下市建议" action={<Badge tone="blue">经理和管理员可汇总查看</Badge>} />{canManage && <div className="mb-4 rounded-2xl bg-[#f8fbff] p-3"><div className="grid gap-2 sm:grid-cols-2"><label className="block"><span className="mb-1 block text-[11px] font-semibold text-[#75594b]">门店</span><select value={form.storeName} disabled={identity.role === "store"} onChange={e => setForm({ ...form, storeName: e.target.value })} className="h-9 w-full rounded-lg border border-[#dce5f4] bg-white px-2 text-xs">{stores.map(s => <option key={s.id}>{s.name}</option>)}</select></label><Field label="产品名称" value={form.productName} onChange={v => setForm({ ...form, productName: v })} placeholder="例如：海盐可颂" required /><label className="block"><span className="mb-1 block text-[11px] font-semibold text-[#75594b]">建议类型</span><select value={form.type} onChange={e => setForm({ ...form, type: e.target.value })} className="h-9 w-full rounded-lg border border-[#dce5f4] bg-white px-2 text-xs"><option>建议下市</option><option>建议上新</option></select></label><label className="block sm:col-span-2"><span className="mb-1 block text-[11px] font-semibold text-[#75594b]">理由和原因</span><textarea value={form.reason} onChange={e => setForm({ ...form, reason: e.target.value })} placeholder="请说明销售、顾客反馈、成本或上新依据" className="min-h-[80px] w-full rounded-lg border border-[#dce5f4] bg-white p-2 text-xs" /></label></div><button disabled={mutation.isPending || !form.productName.trim() || !form.reason.trim()} onClick={() => mutation.mutate({ role: identity.role, identityName: identity.name, identityStoreName: identity.storeName, id: editing?.id, storeName: form.storeName, month: currentMonth, productName: form.productName.trim(), type: form.type as any, reason: form.reason.trim() })} className="mt-3 rounded-xl bg-[#6585b7] px-4 py-2 text-xs font-bold text-white disabled:opacity-50">{mutation.isPending ? "保存中…" : editing ? "保存建议修改" : "提交产品建议"}</button>{editing && <button onClick={() => { setEditing(null); setForm({ storeName: identity.storeName || stores[0]?.name || "", productName: "", type: "建议下市", reason: "" }); }} className="ml-2 rounded-xl bg-[#f1e4d8] px-4 py-2 text-xs font-bold text-[#987d6e]">取消</button>}</div>}{suggestions.length ? <div className="space-y-2">{suggestions.filter(s => s.month === currentMonth).map(item => <div key={item.id} className="rounded-xl border border-[#edf0f5] bg-white p-3"><div className="flex items-start gap-2"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><b className="text-sm text-[#58372c]">{item.productName}</b><Badge tone={item.type === "建议下市" ? "red" : "green"}>{item.type}</Badge></div><div className="mt-1 text-[11px] text-[#a18778]">{item.storeName} · {item.authorName}</div><div className="mt-2 whitespace-pre-wrap text-xs leading-5 text-[#71574b]">{item.reason}</div></div><div className="flex gap-1"><button onClick={() => beginEdit(item)} className="rounded-lg p-2 text-[#a67b63] hover:bg-[#fff3e8]"><Pencil size={14} /></button><button onClick={() => window.confirm("确认删除这条产品建议吗？") && remove.mutate({ role: identity.role, identityName: identity.name, identityStoreName: identity.storeName, id: item.id })} className="rounded-lg p-2 text-[#c8786a] hover:bg-[#fff0ee]"><Trash2 size={14} /></button></div></div></div>)}</div> : <div className="py-6 text-center text-xs text-[#a58d7e]">本月暂无产品上下市建议</div>}</div>;
}

function Monthly({ data, identity, onRefresh }: { data: any; identity: Identity; onRefresh: () => void }) {
  const [selectedMonth, setSelectedMonth] = useState(month());
  const currentMonth = selectedMonth;
  const reports = (data.reports || []).filter((r: any) => r.reportDate.startsWith(currentMonth));
  const byStore = (data.stores || []).filter((s: any) => identity.role === "manager" || identity.role === "admin" || s.name === identity.storeName).map((store: any) => { const own = reports.filter((r: any) => r.storeName === store.name); const revenue = own.reduce((s: number, r: any) => s + n(r.revenue), 0); const target = n(store.monthlyTargetWan) * 10000; return { ...store, revenue, target, progress: target ? revenue / target * 100 : 0 }; });
  const allProducts = (data.products || []).filter((p: any) => identity.role === "manager" || identity.role === "admin" || p.storeName === identity.storeName).filter((p: any) => p.month === currentMonth);
  return <div className="space-y-5"><div className="flex items-end justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">MONTHLY REVIEW</div><h1 className="mt-1 text-2xl font-extrabold tracking-tight text-[#4c2d24]">月汇报</h1><p className="mt-1 text-sm text-[#977a69]">目标、排行与经营策略，一页看清。</p></div><div className="flex items-center gap-2"><input type="month" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} disabled={identity.role === "store"} className="h-10 rounded-xl border border-[#eadbca] bg-white px-3 text-xs text-[#654439]" /><Badge tone="orange">{currentMonth}</Badge></div></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-5"><StatCard icon={TrendingUp} label="本月实收" value={money(reports.reduce((s: number, r: any) => s + n(r.revenue), 0))} detail="累计" tint="bg-[#fff0d4] text-[#bd6c2c]" /><StatCard icon={TrendingDown} label="本月报损" value={money(reports.reduce((s: number, r: any) => s + n(r.wasteAmount), 0))} detail="累计" tint="bg-[#ffe9e3] text-[#c85943]" /><StatCard icon={Target} label="本月储值" value={money(reports.reduce((s: number, r: any) => s + n(r.storedAmount), 0))} detail="累计" tint="bg-[#e3f6e9] text-[#3b8a58]" /><StatCard icon={UsersRound} label="本月客流" value={qty(reports.reduce((s: number, r: any) => s + n(r.traffic), 0))} detail="人次" tint="bg-[#e5f1ff] text-[#4e76a8]" /><StatCard icon={Check} label="本月好评" value={qty(reports.reduce((s: number, r: any) => s + n(r.praiseCount), 0))} detail="累计" tint="bg-[#f1e9ff] text-[#8059aa]" /></div><div><SectionTitle eyebrow="TARGET TRACKING" title="月目标达成" /><div className="grid gap-3 md:grid-cols-2">{byStore.map((store: any) => <div key={store.id} className="soft-card p-4"><div className="flex items-center justify-between"><div><div className="text-sm font-extrabold text-[#58372c]">{store.name}</div><div className="mt-1 text-[11px] text-[#9d8374]">目标 {store.target ? money(store.target) : "未设置目标"}</div></div><div className="text-right"><div className="text-xl font-black text-[#bd6539]">{store.target ? percent(store.progress) : "—"}</div><div className="text-[11px] text-[#9d8374]">已完成 {money(store.revenue)}</div></div></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-[#f0e4d8]" title={`${store.name} 已完成 ${money(store.revenue)}，目标达成 ${percent(store.progress)}`}><div className="h-full rounded-full bg-gradient-to-r from-[#e68149] to-[#f4b56a]" style={{ width: `${Math.min(100, store.progress)}%` }} /></div><div className="mt-2 text-[11px] text-[#a18677]">{store.target ? `还差 ${money(Math.max(0, store.target - store.revenue))}` : "请在门店管理中设置月目标"}</div></div>)}</div></div><div className="grid gap-5 lg:grid-cols-2"><ProductManager products={allProducts} stores={data.stores || []} identity={identity} month={currentMonth} onRefresh={onRefresh} /><ProductSuggestionManager suggestions={data.productSuggestions || []} stores={data.stores || []} identity={identity} month={currentMonth} onRefresh={onRefresh} /><div className="soft-card p-5"><SectionTitle title="月度经营策略" /><textarea placeholder="当月数据总结" className="mb-3 min-h-[100px] w-full rounded-xl border border-[#eadbca] bg-[#fffdfa] p-3 text-sm outline-none focus:ring-2 focus:ring-[#f8dec2]" /><textarea placeholder="下月策略与计划" className="min-h-[100px] w-full rounded-xl border border-[#eadbca] bg-[#fffdfa] p-3 text-sm outline-none focus:ring-2 focus:ring-[#f8dec2]" /><button onClick={() => toast.info("月度总结保存入口已就绪，可继续填写") } className="mt-3 w-full rounded-xl bg-[#f3e4d7] py-2.5 text-xs font-bold text-[#9d5a39]">保存月度总结</button></div></div></div>;
}

function Summary({ data, identity, onRefresh }: { data: any; identity: Identity; onRefresh: () => void }) {
  const [dimension, setDimension] = useState<"day" | "week" | "month" | "custom">("month");
  const [store, setStore] = useState(identity.role === "store" ? identity.storeName || "" : "全部门店");
  const [startDate, setStartDate] = useState(today());
  const [endDate, setEndDate] = useState(today());
  const reports = (data.reports || []).filter((r: any) => !store || store === "全部门店" || r.storeName === store).filter((r: any) => dimension === "custom" ? r.reportDate >= startDate && r.reportDate <= endDate : dimension === "month" ? r.reportDate.startsWith(month()) : dimension === "week" ? r.reportDate >= new Date(Date.now() - 6 * 86400000).toISOString().slice(0, 10) : r.reportDate === today());
  const exportCsv = () => { const rows = [["门店", "日期", "实收", "报损", "储值", "客流", "好评", "填报人"], ...reports.map((r: any) => [r.storeName, r.reportDate, r.revenue, r.wasteAmount, r.storedAmount, r.traffic, r.praiseCount, r.reporter])]; const csv = "\ufeff" + rows.map((row: unknown[]) => row.map((cell: unknown) => `"${String(cell ?? "").replaceAll('"', '""')}"`).join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const a = document.createElement("a"); a.href = url; a.download = `oneira-${dimension}-${today()}.csv`; a.click(); URL.revokeObjectURL(url); toast.success("CSV 已导出"); };
  const stats = { revenue: reports.reduce((s: number, r: any) => s + n(r.revenue), 0), waste: reports.reduce((s: number, r: any) => s + n(r.wasteAmount), 0), stored: reports.reduce((s: number, r: any) => s + n(r.storedAmount), 0), traffic: reports.reduce((s: number, r: any) => s + n(r.traffic), 0), praise: reports.reduce((s: number, r: any) => s + n(r.praiseCount), 0) };
  return <div className="space-y-5">{identity.role === "store" && <DailyReviewPanel data={data} identity={identity} onRefresh={onRefresh} />}<div className="flex flex-wrap items-end justify-between gap-3"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">DATA QUERY</div><h1 className="mt-1 text-2xl font-extrabold tracking-tight text-[#4c2d24]">汇总查询</h1><p className="mt-1 text-sm text-[#977a69]">按时间、门店快速查看经营全貌。</p></div><button onClick={exportCsv} className="flex h-10 items-center gap-2 rounded-xl bg-[#5e3b2e] px-3.5 text-xs font-bold text-white"><Download size={15} /> 导出 CSV</button></div><div className="soft-card flex flex-wrap gap-2 p-3"><div className="flex rounded-xl bg-[#f7f1ea] p-1">{([["day", "按天"], ["week", "按周"], ["month", "按月"], ["custom", "自选日期"]] as const).map(([key, label]) => <button key={key} onClick={() => setDimension(key)} className={`rounded-lg px-3 py-2 text-xs font-bold ${dimension === key ? "bg-white text-[#bf6439] shadow-sm" : "text-[#987d6e]"}`}>{label}</button>)}</div>{dimension === "custom" && <div className="flex items-center gap-1.5"><input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="h-10 rounded-xl border border-[#eadbca] bg-white px-2 text-xs" /><span className="text-xs text-[#a08677]">至</span><input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="h-10 rounded-xl border border-[#eadbca] bg-white px-2 text-xs" /></div>}<select value={store} onChange={e => setStore(e.target.value)} disabled={identity.role === "store"} className="h-10 rounded-xl border border-[#eadbca] bg-white px-3 text-xs font-semibold text-[#654439] outline-none"><option>全部门店</option>{(data.stores || []).map((s: any) => <option key={s.id}>{s.name}</option>)}</select><div className="ml-auto flex items-center gap-1.5 text-[11px] text-[#9f8677]"><CalendarDays size={14} /> {dimension === "custom" ? `${startDate} 至 ${endDate}` : dimension === "day" ? today() : dimension === "week" ? "近 7 天" : month()}</div></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6"><StatCard icon={TrendingUp} label="区间实收" value={money(stats.revenue)} tint="bg-[#fff0d4] text-[#bd6c2c]" /><StatCard icon={TrendingDown} label="区间报损" value={money(stats.waste)} tint="bg-[#ffe9e3] text-[#c85943]" /><StatCard icon={Target} label="区间储值" value={money(stats.stored)} tint="bg-[#e3f6e9] text-[#3b8a58]" /><StatCard icon={UsersRound} label="区间客流" value={qty(stats.traffic)} tint="bg-[#e5f1ff] text-[#4e76a8]" /><StatCard icon={Star} label="区间好评" value={qty(stats.praise)} tint="bg-[#fff3d9] text-[#b8792e]" /><StatCard icon={FileText} label="日报数" value={qty(reports.length)} tint="bg-[#f1e9ff] text-[#8059aa]" /></div><div className="soft-card overflow-hidden"><div className="flex items-center justify-between border-b border-[#f1e6dc] p-4"><div><div className="text-sm font-extrabold text-[#58372c]">各门店明细</div><div className="mt-1 text-[11px] text-[#a08677]">{store === "全部门店" ? "全店汇总" : store} · {reports.length} 条日报</div></div><Badge tone="green">共享数据</Badge></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-xs"><thead className="bg-[#fdf8f3] text-[10px] font-bold text-[#9e8374]"><tr><th className="px-4 py-3">门店 / 日期</th><th className="px-4 py-3">实收</th><th className="px-4 py-3">报损</th><th className="px-4 py-3">储值</th><th className="px-4 py-3">客流</th><th className="px-4 py-3">好评</th><th className="px-4 py-3">状态</th></tr></thead><tbody>{reports.slice(0, 30).map((r: any) => <tr key={r.id} className="border-t border-[#f4e9df] text-[#6c4b3d]"><td className="px-4 py-3"><div className="font-bold">{r.storeName}</div><div className="mt-0.5 text-[10px] text-[#a89081]">{r.reportDate} · {r.reporter}</div></td><td className="px-4 py-3 font-semibold">{money(r.revenue)}</td><td className="px-4 py-3">{money(r.wasteAmount)}</td><td className="px-4 py-3">{money(r.storedAmount)}</td><td className="px-4 py-3">{qty(r.traffic)}</td><td className="px-4 py-3 font-semibold text-[#b8792e]">{qty(r.praiseCount)}</td><td className="px-4 py-3">{r.issue ? <Badge tone={r.issueStatus === "已解决" ? "green" : "red"}>{r.issueStatus}</Badge> : <Badge tone="green">已提交</Badge>}</td></tr>)}</tbody></table>{reports.length === 0 && <div className="p-10 text-center text-sm text-[#a58d7e]">该区间暂无数据</div>}</div></div></div>;
}


function AdminAccessConsole({ onBack }: { onBack: () => void }) {
  const settings = trpc.ops.accessSettings.useQuery({ role: "admin" }, { retry: false });
  const [managerPin, setManagerPin] = useState("");
  const [storePins, setStorePins] = useState<Record<number, string>>({});
  const managerUpdate = trpc.ops.updateManagerPin.useMutation({ onSuccess: () => { toast.success("运营经理口令已更新"); setManagerPin(""); settings.refetch(); }, onError: e => toast.error(e.message) });
  const storeUpdate = trpc.ops.updateStorePin.useMutation({ onSuccess: (_result, variables) => { toast.success("门店登录口令已更新"); const storeId = Number(variables.storeId); setStorePins(current => ({ ...current, [storeId]: "" })); settings.refetch(); }, onError: e => toast.error(e.message) });
  return <div className="absolute inset-0 overflow-y-auto bg-[#f8f0e5] p-4"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#9a6a4e]">ADMIN ACCESS CONSOLE</div><div className="text-lg font-extrabold text-[#58372c]">登录口令控制台</div></div><button onClick={onBack} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">返回</button></div><div className="mb-4 rounded-2xl bg-[#fff1df] p-4 text-xs leading-5 text-[#956b51]">管理员可以在这里设置运营经理口令，以及每个门店的独立登录口令。新口令仅保存云端，不会显示现有口令。</div><div className="soft-card mb-4 p-4"><div className="mb-3 text-sm font-extrabold text-[#58372c]">运营经理登录口令</div><div className="flex gap-2"><input value={managerPin} onChange={e => setManagerPin(e.target.value.replace(/\D/g, "").slice(0, 12))} placeholder="输入 4-12 位数字" inputMode="numeric" className="h-10 min-w-0 flex-1 rounded-xl border border-[#eadbca] bg-white px-3 text-sm tracking-[.25em]" /><button disabled={managerUpdate.isPending || !/^\d{4,12}$/.test(managerPin)} onClick={() => managerUpdate.mutate({ role: "admin", pin: managerPin })} className="rounded-xl bg-[#6b8dbd] px-4 text-xs font-bold text-white disabled:opacity-50">{managerUpdate.isPending ? "保存中…" : "更新口令"}</button></div><div className="mt-2 text-[11px] text-[#a18778]">管理员口令保持独立，目前仍使用系统管理员口令进入控制台。</div></div><div className="soft-card p-4"><div className="mb-3 text-sm font-extrabold text-[#58372c]">各门店独立登录口令</div>{settings.isLoading ? <div className="py-6 text-center text-sm text-[#a58d7e]">正在加载门店…</div> : <div className="space-y-3">{settings.data?.stores.map((store: any) => <div key={store.id} className="rounded-2xl bg-[#fffaf6] p-3"><div className="mb-2 flex items-center justify-between gap-2"><div><div className="text-sm font-bold text-[#5d3d30]">{store.name}</div><div className="text-[10px] text-[#a18778]">店长：{store.managerName} · {store.status}</div></div><Badge tone="blue">独立口令</Badge></div><div className="flex gap-2"><input value={storePins[store.id] || ""} onChange={e => setStorePins({ ...storePins, [store.id]: e.target.value.replace(/\D/g, "").slice(0, 12) })} placeholder="输入新口令" inputMode="numeric" className="h-10 min-w-0 flex-1 rounded-xl border border-[#eadbca] bg-white px-3 text-sm tracking-[.25em]" /><button disabled={storeUpdate.isPending || !/^\d{4,12}$/.test(storePins[store.id] || "")} onClick={() => storeUpdate.mutate({ role: "admin", storeId: store.id, pin: storePins[store.id] })} className="rounded-xl bg-[#e47943] px-4 text-xs font-bold text-white disabled:opacity-50">更新</button></div></div>)}</div>}</div></div>;
}

function ManagerTools({ data, identity, onRefresh, menuOpen, onClose }: { data: any; identity: Identity; onRefresh: () => void; menuOpen: boolean; onClose: () => void }) {
  const [open, setOpen] = useState<"access" | "edit-list" | "store" | "node" | null>(null);
  const [editingStoreId, setEditingStoreId] = useState<number | undefined>();
  const [originalStoreName, setOriginalStoreName] = useState("");
  const [storeForm, setStoreForm] = useState({ name: "", managerName: "", monthlyTargetWan: "", status: "筹备中", openingDate: "" });
  const [nodeForm, setNodeForm] = useState({ storeName: data.stores?.find((s: any) => s.status !== "正常运营")?.name || "", nodeName: "", planDate: "", owner: "", status: "未开始" });
  const storeMutation = trpc.ops.upsertStore.useMutation({ onSuccess: () => { toast.success(editingStoreId ? "门店信息已更新" : "新店已创建"); setOpen(null); setEditingStoreId(undefined); onRefresh(); }, onError: e => toast.error(e.message) });
  const nodeMutation = trpc.ops.upsertNode.useMutation({ onSuccess: () => { toast.success("开业节点已保存"); setOpen(null); onRefresh(); }, onError: e => toast.error(e.message) });
  if (identity.role !== "manager" && identity.role !== "admin") return null;
  if (!menuOpen) return null;
  const beginAdd = () => { setEditingStoreId(undefined); setOriginalStoreName(""); setStoreForm({ name: "", managerName: "", monthlyTargetWan: "", status: "筹备中", openingDate: "" }); setOpen("store"); };
  const beginEdit = (store: any) => { setEditingStoreId(store.id); setOriginalStoreName(store.name); setStoreForm({ name: store.name, managerName: store.managerName || "", monthlyTargetWan: String(store.monthlyTargetWan ?? ""), status: store.status, openingDate: store.openingDate || "" }); setOpen("store"); };
  const closeSubmenu = () => setOpen(null);
  return <div className="fixed inset-0 z-50 flex justify-end"><button aria-label="关闭管理菜单" onClick={onClose} className="absolute inset-0 bg-[#3f281f]/35 backdrop-blur-sm" /><div className="relative h-full w-full max-w-xl overflow-y-auto bg-[#f8f0e5] p-4 shadow-2xl"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">ADMIN MENU</div><div className="text-lg font-extrabold text-[#58372c]">门店管理</div></div><button onClick={onClose} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">关闭</button></div><div className="soft-card p-4"><div className="text-sm font-extrabold text-[#58372c]">总部管理工具</div><div className="mt-1 text-xs text-[#a08677]">选择一个二级菜单后，在弹出界面中查看或编辑</div><div className="mt-4 grid gap-3 sm:grid-cols-2">{identity.role === "admin" && <button onClick={() => setOpen("access")} className="rounded-2xl border border-[#e0d8f2] bg-[#fbf8ff] p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md sm:col-span-2"><div className="text-sm font-extrabold text-[#6d5a9f]">⚿ 管理登录口令</div><div className="mt-1 text-[11px] text-[#8d82ae]">修改运营经理口令，为每个门店设置独立口令</div></button>}<button onClick={beginAdd} className="rounded-2xl border border-[#f0d9bf] bg-[#fff8ee] p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md"><div className="text-sm font-extrabold text-[#9e5d27]">＋ 筹备新店</div><div className="mt-1 text-[11px] text-[#a18778]">填写新店名称、店长、目标和开业日期</div></button><button onClick={() => setOpen("edit-list")} className="rounded-2xl border border-[#eadbca] bg-white p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md"><div className="text-sm font-extrabold text-[#b8653b]">✎ 编辑已有门店</div><div className="mt-1 text-[11px] text-[#a18778]">先选择门店，再打开编辑弹窗</div></button><button onClick={() => setOpen("node")} className="rounded-2xl border border-[#dce5f4] bg-[#f8fbff] p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md sm:col-span-2"><div className="text-sm font-extrabold text-[#4f6e9e]">＋ 管理开业节点</div><div className="mt-1 text-[11px] text-[#8295b4]">为筹备中或装修中的门店添加节点和负责人</div></button></div></div>{open === "access" && <AdminAccessConsole onBack={closeSubmenu} />}{open === "edit-list" && <div className="absolute inset-0 overflow-y-auto bg-[#f8f0e5] p-4"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">STORE DIRECTORY</div><div className="text-lg font-extrabold text-[#58372c]">选择要编辑的门店</div></div><button onClick={closeSubmenu} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">返回</button></div><div className="grid gap-3">{(data.stores || []).map((store: any) => <button key={store.id} onClick={() => beginEdit(store)} className="flex items-center gap-3 rounded-2xl border border-[#f0e3d7] bg-[#fffaf6] p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f8e8d5] text-[#a7653b]"><StoreIcon size={17} /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-extrabold text-[#5d3d30]">{store.name}</div><div className="mt-1 text-[11px] text-[#a18778]">店长：{store.managerName || "未设置"} · 月目标：{store.monthlyTargetWan ?? 0} 万元</div></div><Badge tone={store.status === "正常运营" ? "green" : "orange"}>{store.status}</Badge><ChevronRight size={16} className="text-[#c3a696]" /></button>)}</div></div>}{open === "store" && <div className="absolute inset-0 overflow-y-auto bg-[#f8f0e5] p-4"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">STORE EDITOR</div><div className="text-lg font-extrabold text-[#58372c]">{editingStoreId ? `编辑门店：${originalStoreName}` : "筹备新店"}</div></div><button onClick={closeSubmenu} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">返回</button></div><div className="soft-card p-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="门店名称" value={storeForm.name} onChange={v => setStoreForm({ ...storeForm, name: v })} required /><Field label="店长" value={storeForm.managerName} onChange={v => setStoreForm({ ...storeForm, managerName: v })} required /><Field label="月目标（万元）" value={storeForm.monthlyTargetWan} onChange={v => setStoreForm({ ...storeForm, monthlyTargetWan: v })} type="number" /><Field label="开业日期" value={storeForm.openingDate} onChange={v => setStoreForm({ ...storeForm, openingDate: v })} type="date" /><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">状态</span><select value={storeForm.status} onChange={e => setStoreForm({ ...storeForm, status: e.target.value })} className="h-10 w-full rounded-xl border border-[#eadbca] bg-white px-3 text-sm"><option>正常运营</option><option>筹备中</option><option>装修中</option></select></label></div><button disabled={storeMutation.isPending || !storeForm.name.trim() || !storeForm.managerName.trim()} onClick={() => storeMutation.mutate({ role: identity.role as any, id: editingStoreId, originalName: originalStoreName || undefined, ...storeForm, monthlyTargetWan: n(storeForm.monthlyTargetWan) } as any)} className="mt-4 h-11 w-full rounded-xl bg-[#e47943] text-xs font-bold text-white disabled:opacity-50">{storeMutation.isPending ? "保存中…" : editingStoreId ? "保存门店修改" : "创建筹备新店"}</button>{editingStoreId && <div className="mt-3 text-[11px] leading-5 text-[#a18778]">如果修改门店名称，历史日报、节点、目标、产品和总结会同步更新关联名称。</div>}</div></div>}{open === "node" && <div className="absolute inset-0 overflow-y-auto bg-[#f8f0e5] p-4"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#7b94bd]">OPENING NODE</div><div className="text-lg font-extrabold text-[#58372c]">管理开业节点</div></div><button onClick={closeSubmenu} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">返回</button></div><div className="soft-card p-4"><div className="grid gap-3 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">筹备门店</span><select value={nodeForm.storeName} onChange={e => setNodeForm({ ...nodeForm, storeName: e.target.value })} className="h-10 w-full rounded-xl border border-[#dce5f4] bg-white px-3 text-sm">{(data.stores || []).filter((s: any) => s.status !== "正常运营").map((s: any) => <option key={s.id}>{s.name}</option>)}</select></label><Field label="节点名称" value={nodeForm.nodeName} onChange={v => setNodeForm({ ...nodeForm, nodeName: v })} required /><Field label="计划日期" value={nodeForm.planDate} onChange={v => setNodeForm({ ...nodeForm, planDate: v })} type="date" required /><Field label="负责人" value={nodeForm.owner} onChange={v => setNodeForm({ ...nodeForm, owner: v })} required /></div><button disabled={nodeMutation.isPending} onClick={() => nodeMutation.mutate({ role: identity.role as any, ...nodeForm, completed: nodeForm.status === "已完成" } as any)} className="mt-4 h-11 w-full rounded-xl bg-[#6585b7] text-xs font-bold text-white disabled:opacity-50">{nodeMutation.isPending ? "保存中…" : "保存开业节点"}</button></div></div>}</div></div>;
}


function Issues({ data, identity, onRefresh }: { data: any; identity: Identity; onRefresh: () => void }) {
  const isManager = identity.role === "manager" || identity.role === "admin";
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [selected, setSelected] = useState<any | null>(null);
  const issues = (data.issues || []).filter((item: any) => isManager || item.authorName === identity.name);
  const submit = trpc.ops.submitIssue.useMutation({ onSuccess: () => { toast.success("问题已提交，经理和管理员可以查看"); setTitle(""); setContent(""); onRefresh(); }, onError: e => toast.error(e.message) });
  const remove = trpc.ops.deleteIssue.useMutation({ onSuccess: () => { toast.success("问题已删除"); setSelected(null); onRefresh(); }, onError: e => toast.error(e.message) });
  return <div className="space-y-5"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">ISSUE CENTER</div><h1 className="mt-1 text-2xl font-extrabold tracking-tight text-[#4c2d24]">问题处理</h1><p className="mt-1 text-sm text-[#977a69]">只有遇到问题时再提交，不需要每天填写。</p></div>{!isManager && <div className="soft-card p-5"><SectionTitle title="提交一个问题" /><div className="grid gap-3"><Field label="问题标题" value={title} onChange={setTitle} placeholder="例如：冷柜温度异常" required /><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">问题描述</span><textarea value={content} onChange={e => setContent(e.target.value)} placeholder="请描述发生时间、现象和影响" className="min-h-[120px] w-full rounded-xl border border-[#eadbca] bg-white p-3 text-sm" /></label><button disabled={submit.isPending || !title.trim() || !content.trim()} onClick={() => submit.mutate({ role: "store", identityName: identity.name, storeName: identity.storeName || "", title: title.trim(), content: content.trim() })} className="h-11 rounded-xl bg-[#e47943] text-sm font-bold text-white disabled:opacity-50">{submit.isPending ? "提交中…" : "提交问题"}</button></div></div>}<div className="grid gap-3 md:grid-cols-2">{issues.map((item: any) => <button key={item.id} onClick={() => setSelected(item)} className="soft-card flex items-start gap-3 p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#ffe9e3] text-[#c65044]"><AlertTriangle size={17} /></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="truncate text-sm font-extrabold text-[#58372c]">{item.title}</span><Badge tone={item.status === "已解决" ? "green" : item.status === "处理中" ? "orange" : "red"}>{item.status}</Badge></div><div className="mt-1 text-[11px] text-[#a18778]">{item.storeName} · {item.authorName}</div><div className="mt-2 line-clamp-2 text-xs leading-5 text-[#71574b]">{item.content}</div></div><ChevronRight size={16} className="shrink-0 text-[#c1a697]" /></button>)}{issues.length === 0 && <div className="soft-card p-10 text-center text-sm text-[#a58d7e]">暂无问题记录</div>}</div>{selected && <div className="fixed inset-0 z-[60] flex items-center justify-center p-4"><button onClick={() => setSelected(null)} className="absolute inset-0 bg-[#3f281f]/40 backdrop-blur-sm" /><div className="relative max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-3xl bg-[#f8f0e5] p-5 shadow-2xl"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#bd8462]">ISSUE DETAIL</div><div className="text-lg font-extrabold text-[#58372c]">{selected.title}</div></div><button onClick={() => setSelected(null)} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">关闭</button></div><div className="soft-card p-4"><div className="text-xs leading-6 text-[#71574b] whitespace-pre-wrap">{selected.content}</div><div className="mt-2 text-[11px] text-[#a18778]">{selected.storeName} · {selected.authorName}</div>{isManager && <IssueAction issue={selected} identity={identity} source="store" onRefresh={() => { setSelected(null); onRefresh(); }} />}{!isManager && <button onClick={() => window.confirm("确认删除这条问题吗？删除后无法恢复。") && remove.mutate({ role: "store", identityName: identity.name, identityStoreName: identity.storeName, id: selected.id })} className="mt-4 rounded-xl border border-[#f0c9c1] bg-[#fff3f0] px-4 py-2 text-xs font-bold text-[#c65044]">删除问题</button>}</div></div></div>}</div>;
}

function Suggestions({ identity }: { identity: Identity }) {
  const queryInput = useMemo(() => ({ role: identity.role, storeName: identity.storeName, identityName: identity.name }), [identity.role, identity.storeName, identity.name]);
  const suggestions = trpc.ops.listSuggestions.useQuery(queryInput, { retry: false });
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [replyDrafts, setReplyDrafts] = useState<Record<number, string>>({});
  const [editing, setEditing] = useState<any | null>(null);
  const submit = trpc.ops.submitSuggestion.useMutation({ onSuccess: () => { toast.success("建议已提交，管理员和运营经理可以查看"); setTitle(""); setContent(""); suggestions.refetch(); }, onError: e => toast.error(e.message) });
  const editSuggestion = trpc.ops.editSuggestion.useMutation({ onSuccess: () => { toast.success("建议内容已更新"); setEditing(null); suggestions.refetch(); }, onError: e => toast.error(e.message) });
  const deleteSuggestion = trpc.ops.deleteSuggestion.useMutation({ onSuccess: () => { toast.success("建议已删除"); suggestions.refetch(); }, onError: e => toast.error(e.message) });
  const update = trpc.ops.updateSuggestion.useMutation({ onSuccess: () => { toast.success("建议状态已更新"); suggestions.refetch(); }, onError: e => toast.error(e.message) });
  const isManager = identity.role === "manager" || identity.role === "admin";
  const statusTone = (status: string) => status === "已采纳" ? "green" : status === "处理中" ? "blue" : status === "已回复" ? "orange" : "neutral";
  if (isManager) return <ManagerSuggestionsCompact identity={identity} />;
  return <div className="space-y-5"><div className="soft-card overflow-hidden"><div className="bg-gradient-to-r from-[#fff1df] to-[#fffaf4] p-5"><div className="flex items-start gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#f4b06e] text-white"><MessageCircleWarning size={20} /></div><div><div className="text-lg font-extrabold text-[#58372c]">店长建议</div><div className="mt-1 text-xs leading-5 text-[#9d7d6d]">把一线观察变成门店改进，让每条建议都有回应。</div></div></div></div>{!isManager && <div className="p-5"><div className="grid gap-3"><Field label="建议标题" value={title} onChange={setTitle} placeholder="例如：建议增加下午茶时段套餐" required /><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">详细说明</span><textarea value={content} onChange={e => setContent(e.target.value)} placeholder="请描述现状、建议方案和预期效果" className="min-h-[130px] w-full rounded-xl border border-[#eadbca] bg-white p-3 text-sm leading-6 outline-none focus:ring-2 focus:ring-[#f0a05d]" /></label><button disabled={submit.isPending || !title.trim() || !content.trim()} onClick={() => submit.mutate({ role: "store", identityName: identity.name, storeName: identity.storeName || "", title: title.trim(), content: content.trim() })} className="flex h-11 items-center justify-center gap-2 rounded-xl bg-[#e47943] text-sm font-bold text-white disabled:cursor-not-allowed disabled:opacity-50"><Send size={15} /> {submit.isPending ? "提交中…" : "提交建议"}</button></div></div>}</div><div><SectionTitle eyebrow={isManager ? "TEAM FEEDBACK" : "MY SUGGESTIONS"} title={isManager ? "全部建议" : "我的提交记录"} action={suggestions.data && <Badge tone="orange">{suggestions.data.length} 条</Badge>} />{suggestions.isLoading ? <div className="soft-card p-8 text-center text-sm text-[#a58d7e]">正在加载建议…</div> : suggestions.error ? <div className="soft-card p-8 text-center text-sm text-[#b74335]">建议暂时无法加载，请稍后重试</div> : suggestions.data?.length ? <div className="space-y-3">{suggestions.data.map((item: any) => <div key={item.id} className="soft-card p-4"><div className="flex items-start gap-3"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-extrabold text-[#58372c]">{item.title}</h3><Badge tone={statusTone(item.status) as any}>{item.status}</Badge></div><div className="mt-1 text-[11px] text-[#a18778]">{item.storeName} · {item.authorName} · {new Date(item.createdAt).toLocaleString("zh-CN", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" })}</div></div></div><p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-[#71574b]">{item.content}</p>{!isManager && <div className="mt-3 flex gap-2"><button onClick={() => setEditing(item)} className="flex items-center gap-1 rounded-lg border border-[#eadbca] bg-white px-3 py-2 text-xs font-bold text-[#8f654f]"><Pencil size={13} />编辑</button><button onClick={() => window.confirm("确认删除这条建议吗？删除后无法恢复。") && deleteSuggestion.mutate({ role: "store", identityName: identity.name, identityStoreName: identity.storeName, id: item.id })} className="flex items-center gap-1 rounded-lg border border-[#f0c9c1] bg-[#fff3f0] px-3 py-2 text-xs font-bold text-[#c65044]"><Trash2 size={13} />删除</button></div>}{item.reply && <div className="mt-3 rounded-xl bg-[#f8f1e8] p-3 text-xs leading-5 text-[#765848]"><span className="font-bold text-[#a65f3f]">管理回复：</span>{item.reply}</div>}{isManager && <div className="mt-4 grid gap-2 border-t border-[#f1e6dc] pt-3 sm:grid-cols-[150px_1fr_auto]"><select value={item.status} onChange={e => update.mutate({ role: identity.role as "manager" | "admin", id: item.id, status: e.target.value as any, reply: replyDrafts[item.id] ?? item.reply ?? "" })} className="h-10 rounded-xl border border-[#eadbca] bg-white px-3 text-xs font-semibold text-[#6f5143]"><option>待查看</option><option>处理中</option><option>已采纳</option><option>已回复</option></select><input value={replyDrafts[item.id] ?? item.reply ?? ""} onChange={e => setReplyDrafts({ ...replyDrafts, [item.id]: e.target.value })} placeholder="填写回复（可选）" className="h-10 rounded-xl border border-[#eadbca] bg-white px-3 text-xs outline-none focus:ring-2 focus:ring-[#f0a05d]" /><button onClick={() => update.mutate({ role: identity.role as "manager" | "admin", id: item.id, status: item.status, reply: replyDrafts[item.id] ?? item.reply ?? "" })} className="h-10 rounded-xl bg-[#6b8dbd] px-4 text-xs font-bold text-white">保存处理</button></div>}</div>)}</div> : <div className="soft-card p-10 text-center text-sm text-[#a58d7e]">还没有建议记录</div>}</div>{editing && <div className="fixed inset-0 z-[60] flex items-center justify-center p-4"><button onClick={() => setEditing(null)} className="absolute inset-0 bg-[#3f281f]/40 backdrop-blur-sm" /><div className="relative w-full max-w-lg rounded-3xl bg-[#f8f0e5] p-5 shadow-2xl"><div className="mb-4 flex items-center justify-between"><div className="text-lg font-extrabold text-[#58372c]">编辑建议</div><button onClick={() => setEditing(null)} className="rounded-xl bg-white px-3 py-2 text-xs font-bold text-[#987d6e]">关闭</button></div><div className="soft-card grid gap-3 p-4"><Field label="建议标题" value={editing.title} onChange={value => setEditing({ ...editing, title: value })} required /><label className="block"><span className="mb-1.5 block text-[11px] font-semibold text-[#75594b]">详细说明</span><textarea value={editing.content} onChange={e => setEditing({ ...editing, content: e.target.value })} className="min-h-[130px] w-full rounded-xl border border-[#eadbca] bg-white p-3 text-sm leading-6" /></label><button disabled={editSuggestion.isPending || !editing.title.trim() || !editing.content.trim()} onClick={() => editSuggestion.mutate({ role: "store", identityName: identity.name, identityStoreName: identity.storeName, id: editing.id, title: editing.title.trim(), content: editing.content.trim() })} className="h-11 rounded-xl bg-[#e47943] text-sm font-bold text-white disabled:opacity-50">{editSuggestion.isPending ? "保存中…" : "保存修改"}</button></div></div></div>}</div>;
}

function MainApp({ identity, onSwitch }: { identity: Identity; onSwitch: () => void }) {
  const [tab, setTab] = useState<Tab>("dashboard");
  const [menuOpen, setMenuOpen] = useState(false);
  const queryInput = useMemo(() => ({ role: identity.role, storeName: identity.storeName }), [identity.role, identity.storeName]);
  const bootstrap = trpc.ops.bootstrap.useQuery(queryInput, { retry: false, refetchOnWindowFocus: true });
  const refresh = () => bootstrap.refetch();
  if (bootstrap.isLoading) return <div className="flex min-h-screen items-center justify-center bg-[#f8f0e5] p-6"><div className="text-center"><Loader2 className="mx-auto animate-spin text-[#e47943]" size={28} /><div className="mt-3 text-sm font-bold text-[#654439]">正在同步云端门店数据…</div><div className="mt-1 text-xs text-[#a08677]">多人共享数据加载中，请稍候</div></div></div>;
  if (bootstrap.error || !bootstrap.data) return <div className="flex min-h-screen items-center justify-center bg-[#f8f0e5] p-6"><div className="soft-card w-full max-w-[390px] p-6 text-center"><CloudOff className="mx-auto text-[#c65044]" size={32} /><h2 className="mt-3 font-extrabold text-[#58372c]">云端数据暂时无法加载</h2><p className="mt-2 text-sm leading-6 text-[#9b8172]">{bootstrap.error?.message || "请确认网络已连接，并使用官方 App 或登录后打开。"}</p><button onClick={() => bootstrap.refetch()} className="mt-5 inline-flex items-center gap-2 rounded-xl bg-[#e47943] px-5 py-2.5 text-sm font-bold text-white"><RefreshCw size={15} /> 重新加载</button><button onClick={onSwitch} className="mx-auto mt-3 flex items-center gap-1 text-xs font-semibold text-[#b86a43]">切换身份</button></div></div>;
  const data = bootstrap.data as any;
  const title = { dashboard: "驾驶舱", daily: "日汇报", weekly: "周汇报", monthly: "月汇报", summary: "汇总查询", suggestions: "店长建议", issues: "问题处理" }[tab];
  const icons = { dashboard: LayoutDashboard, daily: ClipboardCheck, weekly: BarChart3, monthly: CalendarDays, summary: PackageSearch, suggestions: MessageCircleWarning, issues: AlertTriangle };
  return <div className="app-shell"><header className="sticky top-0 z-30 border-b border-[#eadbce]/80 bg-[#f8f0e5]/90 backdrop-blur-xl"><div className="app-container !pb-0"><div className="flex h-[68px] items-center justify-between"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f29a52] text-white shadow-[0_6px_14px_rgba(219,113,57,.2)]"><span className="text-xl">✦</span></div><div><div className="text-sm font-extrabold tracking-tight text-[#58372c]">ONEIRA <span className="font-medium text-[#b97a5a]">梦面包</span></div><div className="text-[10px] font-semibold text-[#a18778]">{title}</div></div></div><div className="flex items-center gap-2"><SyncStatus loading={bootstrap.isFetching} syncedAt={data.syncedAt} /><button onClick={refresh} className="rounded-full p-2 text-[#a17f6c] hover:bg-white" title="刷新数据"><RefreshCw size={16} className={bootstrap.isFetching ? "animate-spin" : ""} /></button><button onClick={() => setMenuOpen(true)} className="flex h-8 w-8 items-center justify-center rounded-full bg-[#f0d9bf] text-[#9b5f3f]" title="管理菜单"><Settings2 size={15} /></button><button onClick={onSwitch} className="flex h-8 w-8 items-center justify-center rounded-full bg-[#6b4435] text-white" title="切换身份"><UserRound size={15} /></button></div></div></div></header><main className="app-container pt-5"><div className="mb-4 flex items-center justify-between text-[11px] text-[#a18778]"><div className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-[#5cb87d]" /> {identity.role === "manager" ? "运营经理 · 全店视角" : identity.role === "admin" ? "管理员 · 可编辑门店信息" : `${identity.name} · ${identity.storeName}`}</div><div className="flex items-center gap-1"><Cloud size={12} /> 数据自动同步</div></div>{tab === "dashboard" && <Dashboard data={data} identity={identity} setTab={setTab} onRefresh={refresh} />}{tab === "daily" && (identity.role === "store" ? <DailyReports data={data} identity={identity} onRefresh={refresh} /> : <DailyOverview data={data} identity={identity} />)}{tab === "weekly" && <Weekly data={data} identity={identity} />}{tab === "monthly" && <Monthly data={data} identity={identity} onRefresh={refresh} />}{tab === "summary" && <Summary data={data} identity={identity} onRefresh={refresh} />}{tab === "suggestions" && <Suggestions identity={identity} />} {tab === "issues" && <Issues data={data} identity={identity} onRefresh={refresh} />}</main><ManagerTools data={data} identity={identity} onRefresh={refresh} menuOpen={menuOpen} onClose={() => setMenuOpen(false)} /><nav className="safe-bottom fixed bottom-0 left-0 right-0 z-40 border-t border-[#eadbce] bg-[#fffaf5]/95 backdrop-blur-xl"><div className="mx-auto grid max-w-[700px] grid-cols-7 px-2 py-2">{(Object.keys(icons) as Tab[]).map(key => { const Icon = icons[key]; const active = tab === key; return <button key={key} onClick={() => setTab(key)} className={`flex flex-col items-center gap-1 rounded-xl py-2 text-[10px] font-bold transition ${active ? "bg-[#fff0d4] text-[#bc6437]" : "text-[#a68b7b]"}`}><Icon size={18} strokeWidth={active ? 2.5 : 1.8} /><span>{({ dashboard: "驾驶舱", daily: "日汇报", weekly: "周汇报", monthly: "月汇报", summary: "汇总", suggestions: "建议", issues: "问题" } as any)[key]}</span></button>; })}</div></nav></div>;
}

export default function Home() {
  const [identity, setIdentity] = useState<Identity | null>(() => { try { const stored = localStorage.getItem(IDENTITY_KEY); return stored ? JSON.parse(stored) : null; } catch { return null; } });
  const enter = (next: Identity) => { localStorage.setItem(IDENTITY_KEY, JSON.stringify(next)); setIdentity(next); };
  const switchIdentity = () => { localStorage.removeItem(IDENTITY_KEY); setIdentity(null); };
  return identity ? <MainApp identity={identity} onSwitch={switchIdentity} /> : <IdentityGate onEnter={enter} />;
}
